action.command:
cd /workspace && python3 -c "
import json
spec = json.load(open('contracts/openapi.contract.json'))
for p in sorted(spec['paths'].keys()):
    for m, op in spec['paths'][p].items():
        if m not in ['get','post','put','patch','delete']: continue
        print('='*80)
        print(m.upper(), p, '  operationId=', op.get('operationId'))
        print('  summary:', op.get('summary',''))
        if 'security' in op: print('  security:', op.get('security'))
        if 'parameters' in op:
            print('  PARAMS:')
            for prm in op['parameters']:
                print('    ', prm.get('name'), prm.get('in'), 'required=', prm.get('required'))
                if 'schema' in prm: print('        schema:', json.dumps(prm['schema']))
        if 'requestBody' in op:
            print('  REQUEST BODY:')
            rb = op['requestBody']
            appjson = rb.get('content',{}).get('application/json',{})
            print('    required:', rb.get('required'))
            print('    schema:', json.dumps(appjson.get('schema',{})))
        if 'responses' in op:
            print('  RESPONSES:')
            for code, r in op['responses'].items():
                print('    ', code, r.get('description',''))
                sch = r.get('content',{}).get('application/json',{}).get('schema')
                if sch: print('        schema:', json.dumps(sch))
" > /tmp/ops.txt && wc -l /tmp/ops.txt

