-- Lab Sample Pickup & Delivery - PostgreSQL schema
-- Materialized by the reset command.

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

DROP TABLE IF EXISTS capacity_reservations CASCADE;
DROP TABLE IF EXISTS checkpoints CASCADE;
DROP TABLE IF EXISTS handoffs CASCADE;
DROP TABLE IF EXISTS assignments CASCADE;
DROP TABLE IF EXISTS stops CASCADE;
DROP TABLE IF EXISTS journeys CASCADE;
DROP TABLE IF EXISTS samples CASCADE;
DROP TABLE IF EXISTS requests CASCADE;
DROP TABLE IF EXISTS lab_acceptance CASCADE;
DROP TABLE IF EXISTS connection_capacity CASCADE;
DROP TABLE IF EXISTS connections CASCADE;
DROP TABLE IF EXISTS location_capacity CASCADE;
DROP TABLE IF EXISTS locations CASCADE;
DROP TABLE IF EXISTS sample_types CASCADE;
DROP TABLE IF EXISTS worker_locations CASCADE;
DROP TABLE IF EXISTS disruptions CASCADE;
DROP TABLE IF EXISTS serviceability_versions CASCADE;
DROP TABLE IF EXISTS sessions CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS idempotency_keys CASCADE;
DROP TABLE IF EXISTS settings CASCADE;

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    email TEXT,
    full_name TEXT,
    phone TEXT,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    assigned_location_id UUID,
    roles JSONB NOT NULL DEFAULT '[]',
    qualifications JSONB NOT NULL DEFAULT '[]',
    certifications JSONB NOT NULL DEFAULT '[]',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE sessions (
    token TEXT PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    active_role TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL DEFAULT (now() + interval '24 hours')
);
CREATE INDEX idx_sessions_user ON sessions(user_id);

CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value JSONB NOT NULL
);

CREATE TABLE sample_types (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    qualified_collector_required BOOLEAN NOT NULL DEFAULT FALSE,
    required_qualification TEXT,
    container_type TEXT NOT NULL,
    temperature_min_c DOUBLE PRECISION NOT NULL,
    temperature_max_c DOUBLE PRECISION NOT NULL,
    incompatible_sample_types JSONB NOT NULL DEFAULT '[]',
    requires_cooled_route BOOLEAN NOT NULL DEFAULT FALSE,
    batching_allowed BOOLEAN NOT NULL DEFAULT TRUE,
    is_default BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE locations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    lat DOUBLE PRECISION NOT NULL,
    lon DOUBLE PRECISION NOT NULL,
    coverage_km DOUBLE PRECISION NOT NULL DEFAULT 5,
    handling_minutes INTEGER NOT NULL DEFAULT 0,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    fn_collection_point BOOLEAN NOT NULL DEFAULT FALSE,
    fn_transfer_point BOOLEAN NOT NULL DEFAULT FALSE,
    fn_hub BOOLEAN NOT NULL DEFAULT FALSE,
    fn_laboratory BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_locations_active ON locations(active);

CREATE TABLE location_capacity (
    location_id UUID PRIMARY KEY REFERENCES locations(id) ON DELETE CASCADE,
    capacity_units INTEGER NOT NULL DEFAULT 0,
    cooled_capacity_units INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE connections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    from_location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
    to_location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
    travel_minutes INTEGER NOT NULL,
    cost_units DOUBLE PRECISION NOT NULL DEFAULT 0,
    cooled BOOLEAN NOT NULL DEFAULT FALSE,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_conn_from ON connections(from_location_id);
CREATE INDEX idx_conn_to ON connections(to_location_id);

CREATE TABLE connection_capacity (
    connection_id UUID PRIMARY KEY REFERENCES connections(id) ON DELETE CASCADE,
    capacity_units INTEGER NOT NULL DEFAULT 0,
    cooled_capacity_units INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE lab_acceptance (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    laboratory_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
    sample_type_id UUID NOT NULL REFERENCES sample_types(id) ON DELETE CASCADE,
    accepts BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (laboratory_id, sample_type_id)
);

CREATE TABLE requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    requester_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    origin_type TEXT NOT NULL,
    origin_lat DOUBLE PRECISION,
    origin_lon DOUBLE PRECISION,
    origin_node_id UUID,
    requested_at TIMESTAMPTZ NOT NULL,
    delivery_deadline TIMESTAMPTZ NOT NULL,
    earliest_collection_at TIMESTAMPTZ,
    latest_collection_at TIMESTAMPTZ,
    sample_type_id UUID NOT NULL REFERENCES sample_types(id),
    container_type TEXT NOT NULL,
    temperature_min_c DOUBLE PRECISION NOT NULL,
    temperature_max_c DOUBLE PRECISION NOT NULL,
    incompatible_sample_types JSONB NOT NULL DEFAULT '[]',
    already_sealed BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE samples (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    request_id UUID NOT NULL REFERENCES requests(id) ON DELETE CASCADE,
    requester_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    sample_type_id UUID NOT NULL REFERENCES sample_types(id),
    status TEXT NOT NULL DEFAULT 'pending',
    sealed BOOLEAN NOT NULL DEFAULT FALSE,
    current_holder_id UUID,
    active_journey_id UUID,
    target_laboratory_id UUID,
    origin_type TEXT NOT NULL,
    origin_lat DOUBLE PRECISION,
    origin_lon DOUBLE PRECISION,
    latest_lat DOUBLE PRECISION,
    latest_lon DOUBLE PRECISION,
    location_recorded_at TIMESTAMPTZ,
    serviceability TEXT NOT NULL DEFAULT 'serviceable',
    serviceability_reason TEXT,
    exception JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_samples_requester ON samples(requester_id);
CREATE INDEX idx_samples_holder ON samples(current_holder_id);
CREATE INDEX idx_samples_journey ON samples(active_journey_id);
CREATE INDEX idx_samples_status ON samples(status);

CREATE TABLE journeys (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    parent_journey_id UUID,
    plan_version INTEGER NOT NULL DEFAULT 1,
    route_mode TEXT NOT NULL DEFAULT 'direct',
    status TEXT NOT NULL DEFAULT 'planned',
    estimated_delivery_at TIMESTAMPTZ,
    total_cost_units DOUBLE PRECISION NOT NULL DEFAULT 0,
    sample_ids JSONB NOT NULL DEFAULT '[]',
    valid BOOLEAN NOT NULL DEFAULT TRUE,
    replan_status TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_journeys_parent ON journeys(parent_journey_id);
CREATE INDEX idx_journeys_status ON journeys(status);

CREATE TABLE stops (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
    location_id UUID NOT NULL REFERENCES locations(id),
    stop_type TEXT NOT NULL,
    sequence INTEGER NOT NULL,
    estimated_at TIMESTAMPTZ,
    dwell_minutes INTEGER NOT NULL DEFAULT 0,
    completed_at TIMESTAMPTZ
);
CREATE INDEX idx_stops_journey ON stops(journey_id);

CREATE TABLE assignments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    sequence INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'offered',
    from_location_id UUID REFERENCES locations(id),
    to_location_id UUID REFERENCES locations(id),
    worker_id UUID REFERENCES users(id),
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    node_id UUID REFERENCES locations(id),
    laboratory_id UUID REFERENCES locations(id),
    offer_expires_at TIMESTAMPTZ,
    declined_by JSONB NOT NULL DEFAULT '[]',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_assign_journey ON assignments(journey_id);
CREATE INDEX idx_assign_worker ON assignments(worker_id);
CREATE INDEX idx_assign_sample ON assignments(sample_id);
CREATE INDEX idx_assign_status ON assignments(status);

CREATE TABLE handoffs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    from_assignment_id UUID NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,
    to_assignment_id UUID NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,
    sender_id UUID NOT NULL REFERENCES users(id),
    receiver_id UUID NOT NULL REFERENCES users(id),
    status TEXT NOT NULL DEFAULT 'pending',
    sender_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
    receiver_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
    initiated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    confirmed_at TIMESTAMPTZ
);
CREATE INDEX idx_handoffs_sample ON handoffs(sample_id);

CREATE TABLE checkpoints (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    assignment_id UUID REFERENCES assignments(id) ON DELETE CASCADE,
    location_id UUID REFERENCES locations(id),
    container_type TEXT,
    observed_temperature_c DOUBLE PRECISION,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    compliant BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE capacity_reservations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    resource_type TEXT NOT NULL,
    resource_id UUID NOT NULL,
    journey_id UUID REFERENCES journeys(id) ON DELETE CASCADE,
    assignment_id UUID REFERENCES assignments(id) ON DELETE CASCADE,
    sample_id UUID REFERENCES samples(id) ON DELETE CASCADE,
    regular_units INTEGER NOT NULL DEFAULT 0,
    cooled_units INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_res_resource ON capacity_reservations(resource_type, resource_id);

CREATE TABLE worker_locations (
    worker_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    lat DOUBLE PRECISION,
    lon DOUBLE PRECISION,
    sequence INTEGER NOT NULL DEFAULT 0,
    recorded_at TIMESTAMPTZ,
    available BOOLEAN NOT NULL DEFAULT TRUE,
    capacity_units INTEGER NOT NULL DEFAULT 4
);

CREATE TABLE disruptions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    resource_type TEXT NOT NULL,
    resource_id UUID NOT NULL,
    reason TEXT,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    replan_status TEXT NOT NULL DEFAULT 'not_required',
    affected_sample_ids JSONB NOT NULL DEFAULT '[]',
    replacement_plan_ids JSONB NOT NULL DEFAULT '[]'
);

CREATE TABLE serviceability_versions (
    id SERIAL PRIMARY KEY,
    version INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'complete',
    network_revision INTEGER NOT NULL DEFAULT 0,
    computed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    payload JSONB NOT NULL DEFAULT '{}'
);
CREATE INDEX idx_svc_version ON serviceability_versions(version);

CREATE TABLE idempotency_keys (
    key TEXT PRIMARY KEY,
    user_id UUID,
    operation TEXT NOT NULL,
    response JSONB NOT NULL,
    status_code INTEGER NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

