package main

import (
	"os"
)

type Config struct {
	HTTPAddr        string
	PostgresURL     string
	MongoURI        string
	FrontendDir     string
	MapAssetsDir    string
	AdminUsername   string
	AdminPassword   string
	ResetOnly       bool
	ResetAndSeed    bool
}

func loadConfig() *Config {
	c := &Config{
		HTTPAddr:      envOr("HTTP_ADDR", ":8080"),
		PostgresURL:   envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		MongoURI:      envOr("MONGODB_URI", "mongodb://127.0.0.1:27017/arena"),
		FrontendDir:   envOr("FRONTEND_DIR", "./frontend_dist"),
		MapAssetsDir:  envOr("MAP_ASSETS_DIR", "/workspace/map-assets"),
		AdminUsername: os.Getenv("ADMIN_USERNAME"),
		AdminPassword: os.Getenv("ADMIN_PASSWORD"),
	}
	return c
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

