package main

import (
	"context"
	"fmt"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// Reset drops all Mongo collections and recreates them with indexes, and the
// PG schema is applied separately by the reset command.
func (s *Store) resetMongo(ctx context.Context) error {
	mdb := s.MongoDB
	for _, name := range []string{"audit", "events", "timeline"} {
		_ = mdb.Collection(name).Drop(ctx)
	}
	// Create collections explicitly (materialize) with JSON schema validators.
	if err := mdb.CreateCollection(ctx, "audit"); err != nil {
		// ignore "already exists"
	}
	if err := mdb.CreateCollection(ctx, "events"); err != nil {
		_ = err
	}
	if err := mdb.CreateCollection(ctx, "timeline"); err != nil {
		_ = err
	}
	// Indexes
	_, _ = mdb.Collection("audit").Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "sequence", Value: 1}}, Options: options.Index().SetUnique(true)},
		{Keys: bson.D{{Key: "timestamp", Value: -1}}},
		{Keys: bson.D{{Key: "user_id", Value: 1}}},
		{Keys: bson.D{{Key: "role", Value: 1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
		{Keys: bson.D{{Key: "item_type", Value: 1}, {Key: "item_id", Value: 1}}},
	})
	_, _ = mdb.Collection("events").Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "sequence", Value: 1}}, Options: options.Index().SetUnique(true)},
		{Keys: bson.D{{Key: "sample_id", Value: 1}, {Key: "timestamp", Value: -1}}},
		{Keys: bson.D{{Key: "type", Value: 1}}},
	})
	_, _ = mdb.Collection("timeline").Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "sample_id", Value: 1}, {Key: "sequence", Value: 1}}},
	})
	return nil
}

// seedDefaults inserts the four default sample types if none exist.
func (s *Store) seedDefaults(ctx context.Context) error {
	var n int
	if err := s.PG.QueryRow(ctx, "SELECT count(*) FROM sample_types").Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	defaults := []struct {
		name          string
		qual          bool
		qcode         string
		container     string
		tmin, tmax    float64
		cooled        bool
		batch         bool
	}{
		{"Amber", true, "amber", "standard", 2.0, 25.0, false, true},
		{"Indigo", true, "indigo", "isolated", 2.0, 25.0, false, true},
		{"Frost", true, "frost", "cooled", -20.0, 4.0, true, true},
		{"Pulse", true, "pulse", "standard", 2.0, 25.0, false, false},
	}
	incompat := map[string]string{"Indigo": `["Amber"]`}
	for _, d := range defaults {
		inc := incompat[d.name]
		if inc == "" {
			inc = `[]`
		}
		_, err := s.PG.Exec(ctx, `INSERT INTO sample_types
			(name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed, is_default)
			VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9,true)`,
			d.name, d.qual, d.qcode, d.container, d.tmin, d.tmax, inc, d.cooled, d.batch)
		if err != nil {
			return fmt.Errorf("seed %s: %w", d.name, err)
		}
	}
	return nil
}

