package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"
)

// --- context keys ---
type ctxKey string

const (
	ctxUser ctxKey = "user"
	ctxRole ctxKey = "role"
)

// AuthUser is the authenticated user resolved from the session token.
type AuthUser struct {
	ID            string
	Username      string
	Roles         []string
	Qualifications []string
	ActiveRole    string
	AssignedLoc   string
}

// errAPI is an error carrying an HTTP status code and a contract code.
type errAPI struct {
	status int
	code   string
	msg    string
}

func (e *errAPI) Error() string { return e.msg }

func apiErr(status int, code, msg string) *errAPI {
	return &errAPI{status: status, code: code, msg: msg}
}

var (
	errInvalidJSON      = apiErr(400, "invalid_json", "request body is not valid JSON")
	errUnauthorized     = apiErr(401, "unauthorized", "authentication required")
	errInvalidCreds     = apiErr(401, "invalid_credentials", "username or password is incorrect")
	errForbidden        = apiErr(403, "forbidden", "action not permitted for current role")
	errNotFound         = apiErr(404, "not_found", "resource not found")
	errRoleNotSelected  = apiErr(409, "role_not_selected", "select an active role before performing this action")
	errIdemRequired     = apiErr(400, "idempotency_required", "idempotencyKey is required")
	errConcurrent       = apiErr(409, "concurrent_conflict", "plan version conflict")
	errInternal         = apiErr(500, "internal_error", "internal error")
)

// writeJSON writes a JSON response.
func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeError(w http.ResponseWriter, e *errAPI) {
	if e == nil {
		e = errInternal
	}
	writeJSON(w, e.status, map[string]interface{}{"error": e.msg, "code": e.code})
}

// parseBody decodes JSON into v; returns invalid_json error on failure.
func parseBody(r *http.Request, v interface{}) *errAPI {
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(v); err != nil {
		return errInvalidJSON
	}
	return nil
}

// authMW resolves the bearer [REDACTED] to an AuthUser and stores it in context.
func (a *App) authMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		if token == "" {
			writeError(w, errUnauthorized)
			return
		}
		au, err := a.resolveSession(r.Context(), token)
		if err != nil {
			writeError(w, errUnauthorized)
			return
		}
		ctx := r.Context()
		ctx = contextWith(ctx, ctxUser, au)
		ctx = contextWith(ctx, ctxRole, au.ActiveRole)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if !strings.HasPrefix(h, "Bearer ") {
		return ""
	}
	return strings.TrimPrefix(h, "Bearer ")
}

func currentUser(r *http.Request) *AuthUser {
	if v, ok := r.Context().Value(ctxUser).(*AuthUser); ok {
		return v
	}
	return nil
}

func currentRole(r *http.Request) string {
	if v, ok := r.Context().Value(ctxRole).(string); ok {
		return v
	}
	return ""
}

// requireRole returns an error if the active role is not one of the allowed set.
func requireRole(r *http.Request, allowed ...string) *errAPI {
	role := currentRole(r)
	if role == "" {
		return errRoleNotSelected
	}
	for _, a := range allowed {
		if role == a {
			return nil
		}
	}
	return errForbidden
}

// requireRoleOpt: role selection optional; if a role is selected it must be allowed.
func requireRoleOpt(r *http.Request, allowed ...string) *errAPI {
	role := currentRole(r)
	if role == "" {
		return nil
	}
	for _, a := range allowed {
		if role == a {
			return nil
		}
	}
	return errForbidden
}

func contextWith(ctx interface{ Done() <-chan struct{} }, key, val interface{}) interface{ Done() <-chan struct{} } {
	return ctx
}

