package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"
)

type App struct {
	cfg   *Config
	store *Store
	mux   *http.ServeMux
}

func main() {
	cfg := loadConfig()

	if cfg.ResetOnly {
		if err := runReset(cfg); err != nil {
			fmt.Fprintln(os.Stderr, "reset:", err)
			os.Exit(1)
		}
		return
	}
	if cfg.ResetAndSeed {
		if err := runReset(cfg); err != nil {
			fmt.Fprintln(os.Stderr, "reset:", err)
			os.Exit(1)
		}
	}

	if err := runServer(cfg); err != nil {
		fmt.Fprintln(os.Stderr, "server:", err)
		os.Exit(1)
	}
}

func runReset(cfg *Config) error {
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	store, err := openStore(ctx, cfg)
	if err != nil {
		return err
	}
	defer store.Close()

	schema, err := schemaSQL()
	if err != nil {
		return err
	}
	if _, err := store.PG.Exec(ctx, schema); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	if err := store.resetMongo(ctx); err != nil {
		return fmt.Errorf("reset mongo: %w", err)
	}
	if err := store.seedDefaults(ctx); err != nil {
		return fmt.Errorf("seed defaults: %w", err)
	}
	if err := store.ensureInitialServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	fmt.Println("reset complete")
	return nil
}

func runServer(cfg *Config) error {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	store, err := openStore(ctx, cfg)
	if err != nil {
		return err
	}
	defer store.Close()

	// Ensure schema exists (idempotent) so the app can start even before reset.
	schema, err := schemaSQL()
	if err == nil {
		_, _ = store.PG.Exec(ctx, schema)
	}
	_ = store.seedDefaults(ctx)
	_ = store.ensureInitialServiceability(ctx)

	// Bootstrap admin if no users exist.
	if err := store.bootstrapAdmin(ctx, cfg); err != nil {
		fmt.Fprintln(os.Stderr, "bootstrap admin:", err)
	}

	app := &App{cfg: cfg, store: store, mux: http.NewServeMux()}
	app.registerRoutes()

	srv := &http.Server{
		Addr:    cfg.HTTPAddr,
		Handler: loggingMW(corsMW(app.mux)),
	}

	go app.periodicTasks(ctx)

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	errCh := make(chan error, 1)
	go func() {
		fmt.Println("listening on", cfg.HTTPAddr)
		errCh <- srv.ListenAndServe()
	}()

	select {
	case <-stop:
		ctx2, c2 := context.WithTimeout(context.Background(), 10*time.Second)
		defer c2()
		_ = srv.Shutdown(ctx2)
	case err := <-errCh:
		return err
	}
	return nil
}

func (a *App) periodicTasks(ctx context.Context) {
	t := time.NewTicker(15 * time.Second)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			a.store.expireOffers(ctx)
			a.store.flagDeadlineExceptions(ctx)
		}
	}
}

// registerRoutes wires all 45 endpoints plus the readiness check and static frontend.
func (a *App) registerRoutes() {
	mux := a.mux

	// Readiness (public)
	mux.HandleFunc("/ready", a.handleReadiness)

	// Auth (public)
	mux.HandleFunc("/api/authenticate-user", a.handleAuthenticate)

	// Public GET endpoints that require auth
	mux.Handle("/api/read-sample-state/", a.authMW(http.HandlerFunc(a.handleReadSampleState)))
	mux.Handle("/api/read-user/", a.authMW(http.HandlerFunc(a.handleReadUser)))
	mux.Handle("/api/ui/bootstrap", a.authMW(http.HandlerFunc(a.handleUIBootstrap)))
	mux.Handle("/api/events", a.authMW(http.HandlerFunc(a.handleStreamEvents)))

	// Authenticated POST endpoints. Each handler enforces its own role checks.
	post := func(path string, h http.HandlerFunc) {
		mux.Handle(path, a.authMW(h))
	}
	post("/api/select-active-role", a.handleSelectActiveRole)
	post("/api/check-serviceability", a.handleCheckServiceability)
	post("/api/create-collection-request", a.handleCreateCollectionRequest)
	post("/api/ingest-presealed-sample", a.handleIngestPresealed)
	post("/api/list-role-work", a.handleListRoleWork)
	post("/api/read-journey-plan", a.handleReadJourneyPlan)
	post("/api/read-sample-lifecycle", a.handleReadSampleLifecycle)
	post("/api/read-operations-state", a.handleReadOperationsState)
	post("/api/read-serviceability-snapshot", a.handleReadServiceabilitySnapshot)
	post("/api/search-audit-trail", a.handleSearchAuditTrail)

	post("/api/accept-assignment", a.handleAcceptAssignment)
	post("/api/decline-assignment", a.handleDeclineAssignment)
	post("/api/collect-and-seal-sample", a.handleCollectAndSeal)
	post("/api/record-worker-location", a.handleRecordWorkerLocation)
	post("/api/update-assignment-progress", a.handleUpdateAssignmentProgress)
	post("/api/initiate-handoff", a.handleInitiateHandoff)
	post("/api/confirm-handoff", a.handleConfirmHandoff)
	post("/api/record-handling-checkpoint", a.handleRecordHandlingCheckpoint)
	post("/api/confirm-laboratory-receipt", a.handleConfirmLabReceipt)
	post("/api/record-laboratory-exception", a.handleRecordLabException)
	post("/api/set-worker-availability", a.handleSetWorkerAvailability)

	post("/api/configure-capacity", a.handleConfigureCapacity)
	post("/api/configure-laboratory-acceptance", a.handleConfigureLabAcceptance)
	post("/api/create-location", a.handleCreateLocation)
	post("/api/update-location", a.handleUpdateLocation)
	post("/api/create-connection", a.handleCreateConnection)
	post("/api/set-connection-status", a.handleSetConnectionStatus)
