package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"golang.org/x/crypto/bcrypt"
)

// handleAuthenticate implements POST /api/authenticate-user (auth.login)
func (a *App) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.Username == "" || body.Password == "" {
		writeError(w, errInvalidCreds)
		return
	}
	ctx := r.Context()
	var userID, hash string
	var roles []string
	var active bool
	err := a.store.PG.QueryRow(ctx, `SELECT id, password_hash, roles, active FROM users WHERE username=$1`, body.Username).
		Scan(&userID, &hash, &roles, &active)
	if err != nil || !active {
		writeError(w, errInvalidCreds)
		return
	}
	if err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(body.Password)); err != nil {
		writeError(w, errInvalidCreds)
		return
	}

	token := newToken()
	// Default active role = first role, or "" if none (forces selection).
	activeRole := ""
	if len(roles) > 0 {
		activeRole = roles[0]
	}
	_, err = a.store.PG.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, activeRole)
	if err != nil {
		writeError(w, errConcurrent)
		return
	}

	a.store.audit(ctx, AuditEntry{
		UserID: userID, Username: body.Username, Role: "system", Action: "sign_in",
		ItemType: "user", ItemID: userID, Outcome: "success",
	})

	resp := map[string]interface{}{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	}
	writeData(w, 200, resp)
}

// handleSelectActiveRole implements POST /api/select-active-role
func (a *App) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	var body struct {
		Role string `json:"role"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.Role == "" {
		writeError(w, apiErr(400, "invalid_role", "role is required"))
		return
	}
	allowed := false
	for _, r2 := range au.Roles {
		if r2 == body.Role {
			allowed = true
			break
		}
	}
	if !allowed {
		writeError(w, apiErr(403, "forbidden", "role not assigned to this account"))
		return
	}
	ctx := r.Context()
	// Update all active sessions for the user? Update by token is safest.
	tok := bearerToken(r)
	_, err := a.store.PG.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2 AND user_id=$3`, body.Role, tok, au.ID)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	au.ActiveRole = body.Role
	a.store.audit(ctx, AuditEntry{
		UserID: au.ID, Username: au.Username, Role: body.Role, Action: "select_active_role",
		ItemType: "user", ItemID: au.ID, Outcome: "success",
		Changes: map[string]interface{}{"activeRole": body.Role},
	})
	writeData(w, 200, map[string]interface{}{"activeRole": body.Role, "roles": au.Roles})
}

// bootstrapAdmin creates the initial admin from ADMIN_USERNAME/ADMIN_PASSWORD if no users exist.
func (s *Store) bootstrapAdmin(ctx context.Context, cfg *Config) error {
	var n int
	if err := s.PG.QueryRow(ctx, "SELECT count(*) FROM users").Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	if cfg.AdminUsername == "" || cfg.AdminPassword == "" {
		return errors.New("ADMIN_USERNAME and ADMIN_PASSWORD required for initial admin")
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(cfg.AdminPassword), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	roles := []string{"administrator"}
	rolesJSON, _ := json.Marshal(roles)
	_, err = s.PG.Exec(ctx, `INSERT INTO users (username, password_hash, full_name, roles, active) VALUES ($1,$2,$3,$4,true)`,
		cfg.AdminUsername, string(hash), "Administrator", string(rolesJSON))
	if err != nil {
		return fmt.Errorf("create admin: %w", err)
	}
	return nil
}

// handleReadUser GET /api/read-user/{userId}
func (a *App) handleReadUser(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	userID := pathID(r.URL.Path, "/api/read-user/")
	if userID == "" {
		writeError(w, apiErr(400, "invalid_request", "userId required"))
		return
	}
	// Users can read themselves; admin/dispatcher can read anyone.
	role := currentRole(r)
	if au.ID != userID && role != "administrator" && role != "dispatcher" {
		writeError(w, errForbidden)
		return
	}
	u, err := a.store.getUser(r.Context(), userID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, u)
}

func (s *Store) getUser(ctx context.Context, userID string) (map[string]interface{}, error) {
	var username, email, fullName, phone *string
	var roles, quals []string
	var certs []byte
	var active bool
	err := s.PG.QueryRow(ctx, `
		SELECT username, email, full_name, phone, roles, qualifications, certifications, active
		FROM users WHERE id=$1`, userID).
		Scan(&username, &email, &fullName, &phone, &roles, &quals, &certs, &active)
	if err != nil {
		return nil, err
	}
	var certifications []interface{}
	if err := json.Unmarshal(certs, &certifications); err != nil {
		certifications = []interface{}{}
	}
	u := map[string]interface{}{
		"userId":         userID,
		"username":       strOrEmpty(username),
		"roles":          roles,
		"qualifications": quals,
		"certifications": certifications,
		"active":         active,
	}
	if email != nil {
		u["email"] = *email
	}
	if fullName != nil {
		u["fullName"] = *fullName
	}
	if phone != nil {
		u["phone"] = *phone
	}
	return u, nil
}

func strOrEmpty(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// pathID extracts the trailing path segment after prefix.
func pathID(path, prefix string) string {
	rest := ""
	if len(path) > len(prefix) {
		rest = path[len(prefix):]
	}
	// strip query if any
	for i, c := range rest {
		if c == '?' {
			rest = rest[:i]
			break
		}
	}
	return rest
}

var _ = bson.M{}
var _ = time.Now

