func (a *App) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		Name                     string    `json:"name"`
		QualifiedCollector       bool      `json:"qualifiedCollectorRequired"`
		RequiredQual             string    `json:"requiredQualification"`
		ContainerType            string    `json:"containerType"`
		TempMin                  *float64  `json:"temperatureMinC"`
		TempMax                  *float64  `json:"temperatureMaxC"`
		Incompatible             []string  `json:"incompatibleSampleTypes"`
		RequiresCooled           bool      `json:"requiresCooledRoute"`
		BatchingAllowed          *bool     `json:"batchingAllowed"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.Name == "" || body.ContainerType == "" || body.TempMin == nil || body.TempMax == nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "name, containerType, temp min/max required"))
		return
	}
	if *body.TempMin > *body.TempMax {
		writeError(w, apiErr(400, "invalid_handling_rules", "tempMin must be <= tempMax"))
		return
	}
	batch := true
	if body.BatchingAllowed != nil {
		batch = *body.BatchingAllowed
	}
	if len(body.Incompatible) == 0 {
		body.Incompatible = []string{}
	}
	ctx := r.Context()
	var id string
	err := a.store.PG.QueryRow(ctx, `INSERT INTO sample_types (name,qualified_collector_required,required_qualification,container_type,temperature_min_c,temperature_max_c,incompatible_sample_types,requires_cooled_route,batching_allowed)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id`,
		body.Name, body.QualifiedCollector, nullableStr(body.RequiredQual), body.ContainerType, *body.TempMin, *body.TempMax, toJSON(body.Incompatible), body.RequiresCooled, batch).Scan(&id)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}
	row, _ := a.store.getSampleType(ctx, id)
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "create_sample_type",
		ItemType: "sample_type", ItemID: id, Outcome: "success"})
	writeData(w, 201, stResponse(row))
}

func (a *App) handleUpdateSampleType(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		SampleTypeID   string   `json:"sampleTypeId"`
		Name           *string  `json:"name"`
		QualCollector  *bool    `json:"qualifiedCollectorRequired"`
		ReqQual        *string  `json:"requiredQualification"`
		ContainerType  string   `json:"containerType"`
		TempMin        *float64 `json:"temperatureMinC"`
		TempMax        *float64 `json:"temperatureMaxC"`
		Incompatible   []string `json:"incompatibleSampleTypes"`
		RequiresCooled *bool    `json:"requiresCooledRoute"`
		Batching       *bool    `json:"batchingAllowed"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	row, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	if body.Name != nil {
		row.Name = *body.Name
	}
	if body.QualCollector != nil {
		row.QualifiedCollector = *body.QualCollector
	}
	if body.ReqQual != nil {
		row.RequiredQual = nullableStrPtr(*body.ReqQual)
	}
	row.ContainerType = body.ContainerType
	if body.TempMin != nil {
		row.TempMin = *body.TempMin
	}
	if body.TempMax != nil {
		row.TempMax = *body.TempMax
	}
	if body.Incompatible != nil {
		row.Incompatible = body.Incompatible
	}
	if body.RequiresCooled != nil {
		row.RequiresCooled = *body.RequiresCooled
	}
	if body.Batching != nil {
		row.BatchingAllowed = *body.Batching
	}
	if row.TempMin > row.TempMax {
		writeError(w, apiErr(400, "invalid_handling_rules", "tempMin must be <= tempMax"))
		return
	}
	_, err = a.store.PG.Exec(ctx, `UPDATE sample_types SET name=$1, qualified_collector_required=$2, required_qualification=$3, container_type=$4, temperature_min_c=$5, temperature_max_c=$6, incompatible_sample_types=$7, requires_cooled_route=$8, batching_allowed=$9 WHERE id=$10`,
		row.Name, row.QualifiedCollector, row.RequiredQual, row.ContainerType, row.TempMin, row.TempMax, toJSON(row.Incompatible), row.RequiresCooled, row.BatchingAllowed, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "update_sample_type",
		ItemType: "sample_type", ItemID: body.SampleTypeID, Outcome: "success"})
	writeData(w, 201, stResponse(row))
}

// ---- Capacity ----

type capacityRow struct {
	CapacityUnits            int
	CooledCapacityUnits      int
}

func (s *Store) capacityForLocation(ctx context.Context, id string) (regular, cooled, regRes, coolRes int, err error) {
	var cap, cooled int
	err = s.PG.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM location_capacity WHERE location_id=$1`, id).Scan(&cap, &cooled)
	if err == pgx.ErrNoRows {
		cap, cooled = 0, 0
		err = nil
	}
	if err != nil {
		return
	}
	regular, cooledCap := cap, cooled
	regRes, coolRes = s.reservedLocation(ctx, id)
	regular = regular
	_ = cooledCap
	return regular, cooled, regRes, coolRes, nil
}

func (s *Store) reservedLocation(ctx context.Context, id string) (reg, cooled int) {
	_ = s.PG.QueryRow(ctx, `SELECT COALESCE(sum(regular_units),0), COALESCE(sum(cooled_units),0) FROM capacity_reservations WHERE resource_type='location' AND resource_id=$1`, id).Scan(&reg, &cooled)
	return
}

func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		ResourceID           string `json:"resourceId"`
		CapacityUnits        *int   `json:"capacityUnits"`
		CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.ResourceID == "" || body.CapacityUnits == nil {
		writeError(w, apiErr(400, "invalid_capacity", "resourceId and capacityUnits required"))
		return
	}
	cooled := 0
	if body.CooledCapacityUnits != nil {
		cooled = *body.CooledCapacityUnits
	}
	ctx := r.Context()
	// Determine resource type: location or connection.
	var isLoc, isConn bool
	_ = a.store.PG.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, body.ResourceID).Scan(&isLoc)
	_ = a.store.PG.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM connections WHERE id=$1)`, body.ResourceID).Scan(&isConn)
	if !isLoc && !isConn {
		writeError(w, errNotFound)
		return
	}
	// Guard against overbook: cannot set capacity below currently reserved.
	regRes, coolRes := 0, 0
	if isLoc {
		regRes, coolRes = a.store.reservedLocation(ctx, body.ResourceID)
	} else {
		_ = a.store.PG.QueryRow(ctx, `SELECT COALESCE(sum(regular_units),0), COALESCE(sum(cooled_units),0) FROM capacity_reservations WHERE resource_type='connection' AND resource_id=$1`, body.ResourceID).Scan(&regRes, &coolRes)
	}
	if *body.CapacityUnits < regRes || cooled < coolRes {
		writeError(w, apiErr(409, "capacity_reserved", "cannot reduce capacity below reserved units"))
		return
	}
	if isLoc {
		_, err := a.store.PG.Exec(ctx, `INSERT INTO location_capacity (location_id, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3)
			ON CONFLICT (location_id) DO UPDATE SET capacity_units=$2, cooled_capacity_units=$3`, body.ResourceID, *body.CapacityUnits, cooled)
		if err != nil {
			writeError(w, errInternal)
			return
		}
	} else {
		_, err := a.store.PG.Exec(ctx, `INSERT INTO connection_capacity (connection_id, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3)
			ON CONFLICT (connection_id) DO UPDATE SET capacity_units=$2, cooled_capacity_units=$3`, body.ResourceID, *body.CapacityUnits, cooled)
		if err != nil {
			writeError(w, errInternal)
			return
		}
	}
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "configure_capacity",
		ItemType: "capacity", ItemID: body.ResourceID, Outcome: "success",
		Changes: map[string]interface{}{"capacityUnits": *body.CapacityUnits, "cooledCapacityUnits": cooled}})
	writeData(w, 200, map[string]interface{}{
		"resourceId":            body.ResourceID,
		"capacityUnits":         *body.CapacityUnits,
		"cooledCapacityUnits":   cooled,
	})
}

// handleConfigureLabAcceptance POST /api/configure-laboratory-acceptance
func (a *App) handleConfigureLabAcceptance(w http.ResponseWriter, r *http.Request) {
