// ---- Locations ----

type locationRow struct {
	ID             string
	Name           string
	Lat, Lon       float64
	CoverageKm     float64
	HandlingMin    int
	Active         bool
	FnColl, FnTrans, FnHub, FnLab bool
}

func (s *Store) locationFromRow(r locationRow) map[string]interface{} {
	return map[string]interface{}{
		"locationId":      r.ID,
		"name":            r.Name,
		"coordinate":      map[string]interface{}{"latitude": r.Lat, "longitude": r.Lon},
		"coverageKm":      r.CoverageKm,
		"handlingMinutes": r.HandlingMin,
		"active":          r.Active,
