// ---- Connections ----

func (a *App) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.TravelMinutes < 1 {
		writeError(w, apiErr(400, "invalid_connection", "travelMinutes must be >= 1"))
		return
	}
	if body.FromLocationID == "" || body.ToLocationID == "" {
		writeError(w, apiErr(400, "invalid_connection", "from/to required"))
		return
	}
	ctx := r.Context()
	var id string
	err := a.store.PG.QueryRow(ctx, `INSERT INTO connections (from_location_id,to_location_id,travel_minutes,cost_units,cooled,active)
		VALUES ($1,$2,$3,$4,$5,$6) RETURNING id`,
		body.FromLocationID, body.ToLocationID, body.TravelMinutes, body.CostUnits, body.Cooled, body.Active).Scan(&id)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}
	_, _ = a.store.PG.Exec(ctx, `INSERT INTO connection_capacity (connection_id) VALUES ($1) ON CONFLICT DO NOTHING`, id)
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "create_connection",
		ItemType: "connection", ItemID: id, Outcome: "success"})
	a.store.bumpNetworkRevision(ctx)
	writeData(w, 201, map[string]interface{}{
