func (a *App) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.TravelMinutes < 1 {
		writeError(w, apiErr(400, "invalid_connection", "travelMinutes must be >= 1"))
		return
	}
	if body.FromLocationID == "" || body.ToLocationID == "" {
		writeError(w, apiErr(400, "invalid_connection", "from/to required"))
		return
	}
	ctx := r.Context()
	var id string
