	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}
	_, _ = a.store.PG.Exec(ctx, `INSERT INTO connection_capacity (connection_id) VALUES ($1) ON CONFLICT DO NOTHING`, id)
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "create_connection",
		ItemType: "connection", ItemID: id, Outcome: "success"})
	a.store.bumpNetworkRevision(ctx)
	writeData(w, 201, map[string]interface{}{
		"connectionId":   id,
		"fromLocationId": body.FromLocationID,
		"toLocationId":   body.ToLocationID,
		"travelMinutes":  body.TravelMinutes,
		"costUnits":      body.CostUnits,
		"cooled":         body.Cooled,
		"active":         body.Active,
	})
}

