// ---- helpers ----

func toJSON(v interface{}) interface{} { return pgJSON(v) }
func toJSONStr(v interface{}) string    { b, _ := json.Marshal(v); return string(b) }
func nullableStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}
func nullableStrPtr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}
func nullableUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return pgtype.UUID{}
}

func bcryptHash(pw string) (string, error) {
	h, err := bcryptGenerate([]byte(pw))
	return string(h), err
}

