}

// ---- Sample types ----

type sampleTypeRow struct {
	ID                       string
	Name                     string
	QualifiedCollector       bool
	RequiredQual             *string
	ContainerType            string
	TempMin, TempMax         float64
	Incompatible             []string
	RequiresCooled           bool
	BatchingAllowed          bool
}

func (s *Store) getSampleType(ctx context.Context, id string) (*sampleTypeRow, error) {
	var r sampleTypeRow
	err := s.PG.QueryRow(ctx, `SELECT id,name,qualified_collector_required,required_qualification,container_type,temperature_min_c,temperature_max_c,incompatible_sample_types,requires_cooled_route,batching_allowed FROM sample_types WHERE id=$1`, id).
		Scan(&r.ID, &r.Name, &r.QualifiedCollector, &r.RequiredQual, &r.ContainerType, &r.TempMin, &r.TempMax, &r.Incompatible, &r.RequiresCooled, &r.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	return &r, nil
}

func stResponse(r *sampleTypeRow) map[string]interface{} {
	req := ""
	if r.RequiredQual != nil {
		req = *r.RequiredQual
	}
	return map[string]interface{}{
		"sampleTypeId":              r.ID,
		"name":                      r.Name,
		"qualifiedCollectorRequired": r.QualifiedCollector,
		"requiredQualification":     req,
