func (a *App) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		UserID         string                 `json:"userId"`
		Roles          []string               `json:"roles"`
		Qualifications []string               `json:"qualifications"`
		Certifications []map[string]interface{} `json:"certifications"`
		Active         bool                   `json:"active"`
		AssignedLoc    string                 `json:"assignedLocationId"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.UserID == "" || len(body.Roles) == 0 {
		writeError(w, apiErr(400, "invalid_request", "userId and roles required"))
		return
	}
	ctx := r.Context()
	_, err := a.store.PG.Exec(ctx, `UPDATE users SET roles=$1, qualifications=$2, certifications=$3, active=$4, assigned_location_id=$5 WHERE id=$6`,
		pgJSONStr(body.Roles), pgJSONStr(body.Qualifications), pgJSONStr(body.Certifications), body.Active, nullableUUID(body.AssignedLoc), body.UserID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "update_user_access",
		ItemType: "user", ItemID: body.UserID, Outcome: "success"})
	u, _ := a.store.getUser(ctx, body.UserID)
	writeData(w, 201, u)
}

// ---- helpers ----

func nullableStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}
func nullableStrPtr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}
func nullableUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func bcryptHash(pw string) (string, error) {
	h, err := bcryptGenerate([]byte(pw))
	return string(h), err
}

