// ---- Capacity ----

type capacityRow struct {
	CapacityUnits            int
	CooledCapacityUnits      int
}

func (s *Store) capacityForLocation(ctx context.Context, id string) (regular, cooled, regRes, coolRes int, err error) {
	var cap, cooled int
	err = s.PG.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM location_capacity WHERE location_id=$1`, id).Scan(&cap, &cooled)
	if err == pgx.ErrNoRows {
		cap, cooled = 0, 0
		err = nil
	}
	if err != nil {
		return
	}
	regular, cooledCap := cap, cooled
	regRes, coolRes = s.reservedLocation(ctx, id)
	regular = regular
	_ = cooledCap
	return regular, cooled, regRes, coolRes, nil
}

func (s *Store) reservedLocation(ctx context.Context, id string) (reg, cooled int) {
	_ = s.PG.QueryRow(ctx, `SELECT COALESCE(sum(regular_units),0), COALESCE(sum(cooled_units),0) FROM capacity_reservations WHERE resource_type='location' AND resource_id=$1`, id).Scan(&reg, &cooled)
	return
}

func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		ResourceID           string `json:"resourceId"`
		CapacityUnits        *int   `json:"capacityUnits"`
		CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.ResourceID == "" || body.CapacityUnits == nil {
		writeError(w, apiErr(400, "invalid_capacity", "resourceId and capacityUnits required"))
		return
	}
	cooled := 0
	if body.CooledCapacityUnits != nil {
		cooled = *body.CooledCapacityUnits
	}
	ctx := r.Context()
	// Determine resource type: location or connection.
	var isLoc, isConn bool
	_ = a.store.PG.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, body.ResourceID).Scan(&isLoc)
	_ = a.store.PG.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM connections WHERE id=$1)`, body.ResourceID).Scan(&isConn)
	if !isLoc && !isConn {
		writeError(w, errNotFound)
		return
	}
	// Guard against overbook: cannot set capacity below currently reserved.
	regRes, coolRes := 0, 0
	if isLoc {
		regRes, coolRes = a.store.reservedLocation(ctx, body.ResourceID)
	} else {
		_ = a.store.PG.QueryRow(ctx, `SELECT COALESCE(sum(regular_units),0), COALESCE(sum(cooled_units),0) FROM capacity_reservations WHERE resource_type='connection' AND resource_id=$1`, body.ResourceID).Scan(&regRes, &coolRes)
	}
	if *body.CapacityUnits < regRes || cooled < coolRes {
		writeError(w, apiErr(409, "capacity_reserved", "cannot reduce capacity below reserved units"))
		return
	}
	if isLoc {
		_, err := a.store.PG.Exec(ctx, `INSERT INTO location_capacity (location_id, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3)
			ON CONFLICT (location_id) DO UPDATE SET capacity_units=$2, cooled_capacity_units=$3`, body.ResourceID, *body.CapacityUnits, cooled)
		if err != nil {
			writeError(w, errInternal)
			return
		}
	} else {
		_, err := a.store.PG.Exec(ctx, `INSERT INTO connection_capacity (connection_id, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3)
			ON CONFLICT (connection_id) DO UPDATE SET capacity_units=$2, cooled_capacity_units=$3`, body.ResourceID, *body.CapacityUnits, cooled)
		if err != nil {
			writeError(w, errInternal)
			return
		}
	}
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "configure_capacity",
		ItemType: "capacity", ItemID: body.ResourceID, Outcome: "success",
		Changes: map[string]interface{}{"capacityUnits": *body.CapacityUnits, "cooledCapacityUnits": cooled}})
	writeData(w, 200, map[string]interface{}{
		"resourceId":            body.ResourceID,
		"capacityUnits":         *body.CapacityUnits,
		"cooledCapacityUnits":   cooled,
	})
}

