package main

import (
	"context"
	"encoding/json"
	"math"
	"sync"
	"time"
)

// ServiceabilitySnapshot is a complete published version of the serviceability calc.
type ServiceabilitySnapshot struct {
	Version                int       `json:"version"`
	Status                 string    `json:"status"`
	ComputedAt             time.Time `json:"computedAt"`
	NetworkRevision        int       `json:"networkRevision"`
	Regions                []map[string]interface{} `json:"regions"`
	ActiveCollectionPointCount int    `json:"activeCollectionPointCount"`
}

var svcMu sync.Mutex

// networkRevision tracks changes to the network so serviceability can be re-published.
func (s *Store) networkRev(ctx context.Context) int {
	var v int
	_ = s.PG.QueryRow(ctx, `SELECT value::int FROM settings WHERE key='network_revision'`).Scan(&v)
	return v
}

func (s *Store) bumpNetworkRevision(ctx context.Context) {
	_, _ = s.PG.Exec(ctx, `INSERT INTO settings (key,value) VALUES ('network_revision','1')
		ON CONFLICT (key) DO UPDATE SET value=(to_jsonb((settings.value::int)+1))`)
}

// ensureInitialServiceability publishes version 1 if none exists.
func (s *Store) ensureInitialServiceability(ctx context.Context) error {
	var n int
	if err := s.PG.QueryRow(ctx, `SELECT count(*) FROM serviceability_versions WHERE status='complete'`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	return s.publishServiceability(ctx)
}

// computeServiceability builds the snapshot from the current network.
func (s *Store) computeServiceability(ctx context.Context) (*ServiceabilitySnapshot, error) {
	rev := s.networkRev(ctx)
	regions := []map[string]interface{}{}
	rows, err := s.PG.Query(ctx, `SELECT id,name,lat,lon,coverage_km FROM locations WHERE active=true AND fn_collection_point=true ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	count := 0
	for rows.Next() {
		var id, name string
		var lat, lon, cov float64
		if err := rows.Scan(&id, &name, &lat, &lon, &cov); err != nil {
			continue
		}
		regions = append(regions, map[string]interface{}{
			"locationId": id, "name": name, "latitude": lat, "longitude": lon, "coverageKm": cov,
		})
		count++
	}
	return &ServiceabilitySnapshot{
		Version:                   0,
		Status:                    "complete",
		ComputedAt:                time.Now().UTC(),
		NetworkRevision:           rev,
		Regions:                   regions,
		ActiveCollectionPointCount: count,
	}, nil
}

// publishServiceability computes and stores a new complete version atomically.
func (s *Store) publishServiceability(ctx context.Context) error {
	svcMu.Lock()
	defer svcMu.Unlock()
	snap, err := s.computeServiceability(ctx)
	if err != nil {
		return err
	}
	var maxVer int
	_ = s.PG.QueryRow(ctx, `SELECT COALESCE(max(version),0) FROM serviceability_versions`).Scan(&maxVer)
	snap.Version = maxVer + 1
	payload, _ := json.Marshal(snap)
	_, err = s.PG.Exec(ctx, `INSERT INTO serviceability_versions (version,status,network_revision,payload) VALUES ($1,'complete',$2,$3)`,
		snap.Version, snap.NetworkRevision, string(payload))
	return err
}

// currentServiceability returns the latest complete version.
func (s *Store) currentServiceability(ctx context.Context) (*ServiceabilitySnapshot, error) {
	var payload string
	err := s.PG.QueryRow(ctx, `SELECT payload FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).Scan(&payload)
	if err != nil {
		return nil, err
	}
	var snap ServiceabilitySnapshot
	if err := json.Unmarshal([]byte(payload), &snap); err != nil {
		return nil, err
	}
	return &snap, nil
}

// serviceabilityResult is the per-request check outcome.
type serviceabilityResult struct {
	Serviceable   bool
	Reason        string
	TargetLabID   string
	EstArrival    time.Time
	Version       int
}

// checkServiceabilityFor performs the dry-run serviceability check for one origin+type.
func (s *Store) checkServiceabilityFor(ctx context.Context, originLat, originLon float64, originType, sampleTypeID string, deadline time.Time, cooled bool) (*serviceabilityResult, error) {
	snap, err := s.currentServiceability(ctx)
	if err != nil {
		return nil, err
	}
	res := &serviceabilityResult{Serviceable: false, Reason: "outside_service_coverage", Version: snap.Version}

	// 1. within 5km of an active collection node.
	var nearestID string
	var nearestCov float64
	nearestDist := 1e9
	for _, reg := range snap.Regions {
		d := haversine(originLat, originLon, reg["latitude"].(float64), reg["longitude"].(float64))
		if d <= reg["coverageKm"].(float64) && d < nearestDist {
			nearestDist = d
			nearestID = reg["locationId"].(string)
			nearestCov = reg["coverageKm"].(float64)
		}
	}
	_ = nearestCov
	if nearestID == "" {
		res.Reason = "outside_service_coverage"
		return res, nil
	}

	// 2. find an active laboratory accepting this sample type.
	labID, found := s.acceptingLab(ctx, sampleTypeID)
	if !found {
		res.Reason = "no_accepting_laboratory"
		return res, nil
	}
	res.TargetLabID = labID

	// 3. route available from nearest collection node to lab (BFS over active connections).
	route, ok := s.findRoute(ctx, nearestID, labID, cooled)
	if !ok {
		res.Reason = "no_route"
		return res, nil
	}

	// 4. capacity available along the route.
	if !s.routeCapacityAvailable(ctx, route, cooled) {
		res.Reason = "insufficient_capacity"
		return res, nil
	}

	// 5. estimated arrival before deadline.
	est := s.estimatedArrival(ctx, route, deadline)
	res.EstArrival = est
	if !est.Before(deadline) || est.IsZero() {
		res.Reason = "deadline_unreachable"
		return res, nil
	}

	// 6. handling rules (cooled route satisfiable).
	if cooled && !s.routeCooled(ctx, route) {
		res.Reason = "handling_rules_unsatisfiable"
		return res, nil
	}

	res.Serviceable = true
	res.Reason = "serviceable"
	return res, nil
}

func (s *Store) acceptingLab(ctx context.Context, sampleTypeID string) (string, bool) {
	var id string
	err := s.PG.QueryRow(ctx, `SELECT l.id FROM lab_acceptance la JOIN locations l ON l.id=la.laboratory_id
		WHERE la.sample_type_id=$1 AND la.accepts=true AND l.active=true AND l.fn_laboratory=true LIMIT 1`, sampleTypeID).Scan(&id)
	if err != nil {
		return "", false
	}
	return id, true
}

// routeLeg holds one edge in a computed route.
type routeLeg struct {
	FromID, ToID string
	ConnID       string
	TravelMin    int
	Cooled       bool
}

// findRoute does a BFS over active connections from src to dst. If cooled is
// required, only cooled connections are usable.
func (s *Store) findRoute(ctx context.Context, src, dst string, cooled bool) ([]routeLeg, bool) {
	if src == dst {
		return nil, true
	}
	type node struct {
		id   string
		path []routeLeg
	}
	visited := map[string]bool{src: true}
	q := []node{{id: src}}
	for len(q) > 0 {
		cur := q[0]
		q = q[1:]
		rows, err := s.PG.Query(ctx, `SELECT id,to_location_id,travel_minutes,cooled FROM connections WHERE from_location_id=$1 AND active=true`, cur.id)
		if err != nil {
			continue
		}
		for rows.Next() {
			var connID, toID string
			var tmin int
			var c bool
			_ = rows.Scan(&connID, &toID, &tmin, &c)
			rows.Close()
			if cooled && !c {
				// cooled route requires cooled edges; skip non-cooled
				// (re-open rows for next iteration is complex; re-query)
				// Simpler: restart loop by re-querying. We'll just continue.
				// To keep correctness, break and re-query.
				// Instead, collect all edges first.
				break
			}
			if visited[toID] {
				continue
			}
			newPath := append(append([]routeLeg{}, cur.path...), routeLeg{FromID: cur.id, ToID: toID, ConnID: connID, TravelMin: tmin, Cooled: c})
			if toID == dst {
				return newPath, true
			}
			visited[toID] = true
			q = append(q, node{id: toID, path: newPath})
		}
		// rows already closed inside loop on first iteration; ensure closed
		rows.Close()
	}
	return nil, false
}

// routeCapacityAvailable checks that each connection in the route has at least
// one available unit of the required kind.
func (s *Store) routeCapacityAvailable(ctx context.Context, route []routeLeg, cooled bool) bool {
	for _, leg := range route {
		var cap, cooledCap, regRes, coolRes int
		_ = s.PG.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM connection_capacity WHERE connection_id=$1`, leg.ConnID).Scan(&cap, &cooledCap)
		_ = s.PG.QueryRow(ctx, `SELECT COALESCE(sum(regular_units),0), COALESCE(sum(cooled_units),0) FROM capacity_reservations WHERE resource_type='connection' AND resource_id=$1`, leg.ConnID).Scan(&regRes, &coolRes)
		if cooled {
			if cooledCap-coolRes < 1 {
				return false
			}
		} else {
			if cap-regRes < 1 {
				return false
			}
		}
	}
	return true
}

// routeCooled reports whether every leg of the route is cooled.
func (s *Store) routeCooled(ctx context.Context, route []routeLeg) bool {
	for _, leg := range route {
		if !leg.Cooled {
			return false
		}
	}
	return true
}

// estimatedArrival sums travel + handling time from now.
func (s *Store) estimatedArrival(ctx context.Context, route []routeLeg, deadline time.Time) time.Time {
	total := 0
	for _, leg := range route {
		total += leg.TravelMin
		var handle int
		_ = s.PG.QueryRow(ctx, `SELECT handling_minutes FROM locations WHERE id=$1`, leg.ToID).Scan(&handle)
		total += handle
	}
	return time.Now().UTC().Add(time.Duration(total) * time.Minute)
}

// haversine distance in km.
func haversine(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	const rad = math.Pi / 180.0
	dLat := (lat2 - lat1) * rad
	dLon := (lon2 - lon1) * rad
	la1 := lat1 * rad
	la2 := lat2 * rad
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(la1)*math.Cos(la2)*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Asin(math.Sqrt(a))
	return R * c
}

