	"fmt"
	"net/http"
	"time"
)

// handleCheckServiceability POST /api/check-serviceability (dry run)
func (a *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "requester", "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		OriginType         string                 `json:"originType"`
		OriginCoordinate   map[string]float64     `json:"originCoordinate"`
		OriginNodeID       string                 `json:"originNodeId"`
		SampleTypeID       string                 `json:"sampleTypeId"`
		DeliveryDeadline   string                 `json:"deliveryDeadline"`
		EarliestCollection string                 `json:"earliestCollectionAt"`
		LatestCollection   string                 `json:"latestCollectionAt"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.SampleTypeID == "" || body.DeliveryDeadline == "" {
		writeError(w, apiErr(400, "invalid_request", "sampleTypeId and deliveryDeadline required"))
		return
	}
	deadline, err := time.Parse(time.RFC3339, body.DeliveryDeadline)
	if err != nil {
		writeError(w, apiErr(400, "invalid_deadline", "deliveryDeadline must be RFC3339"))
		return
	}
	ctx := r.Context()
	st, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "unknown sample type"))
		return
	}

	var oLat, oLon float64
	if body.OriginType == "home" || body.OriginType == "clinic" {
		if body.OriginCoordinate == nil {
			writeError(w, apiErr(400, "invalid_coordinate", "originCoordinate required"))
			return
		}
		oLat = body.OriginCoordinate["latitude"]
		oLon = body.OriginCoordinate["longitude"]
	} else if body.OriginType == "node" {
		loc, err := a.store.getLocation(ctx, body.OriginNodeID)
		if err != nil {
			writeError(w, apiErr(400, "invalid_request", "unknown origin node"))
			return
		}
		oLat, oLon = loc.Lat, loc.Lon
	} else {
		writeError(w, apiErr(400, "invalid_request", "originType must be home, clinic or node"))
		return
	}

	res, err := a.store.checkServiceabilityFor(ctx, oLat, oLon, body.OriginType, body.SampleTypeID, deadline, st.RequiresCooled)
	if err != nil {
		writeError(w, errInternal)
		return
	}

	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "check_serviceability",
		ItemType: "serviceability", Outcome: "success",
		Changes: map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason}})

	snap, _ := a.store.currentServiceability(ctx)
	resp := map[string]interface{}{
		"serviceable":            res.Serviceable,
		"reason":                  res.Reason,
		"serviceabilityVersion":   res.Version,
	}
	if res.TargetLabID != "" {
		resp["targetLaboratoryId"] = res.TargetLabID
	}
	if !res.EstArrival.IsZero() {
		resp["estimatedArrivalAt"] = res.EstArrival.UTC().Format(time.RFC3339)
	}
	if snap != nil {
		resp["serviceabilityVersion"] = snap.Version
	}
	resp["deadline"] = deadline.UTC().Format(time.RFC3339)
	writeData(w, 200, resp)
}

// handleCreateCollectionRequest POST /api/create-collection-request
func (a *App) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "requester", "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		OriginType         string                 `json:"originType"`
		OriginCoordinate   map[string]float64     `json:"originCoordinate"`
		OriginNodeID       string                 `json:"originNodeId"`
		SampleTypeID       string                 `json:"sampleTypeId"`
		DeliveryDeadline   string                 `json:"deliveryDeadline"`
		EarliestCollection string                 `json:"earliestCollectionAt"`
		LatestCollection   string                 `json:"latestCollectionAt"`
		Notes              string                 `json:"notes"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.SampleTypeID == "" || body.DeliveryDeadline == "" || body.OriginType == "" {
		writeError(w, apiErr(400, "invalid_request", "originType, sampleTypeId, deliveryDeadline required"))
		return
	}
	deadline, err := time.Parse(time.RFC3339, body.DeliveryDeadline)
	if err != nil {
		writeError(w, apiErr(400, "invalid_deadline", "deliveryDeadline must be RFC3339"))
		return
	}
	ctx := r.Context()
	st, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "unknown sample type"))
		return
	}

	var oLat, oLon float64
	var oNodeID interface{}
	if body.OriginType == "home" || body.OriginType == "clinic" {
		if body.OriginCoordinate == nil {
			writeError(w, apiErr(400, "invalid_coordinate", "originCoordinate required"))
			return
		}
		oLat = body.OriginCoordinate["latitude"]
		oLon = body.OriginCoordinate["longitude"]
	} else if body.OriginType == "node" {
		loc, err := a.store.getLocation(ctx, body.OriginNodeID)
		if err != nil {
			writeError(w, apiErr(400, "invalid_request", "unknown origin node"))
			return
		}
		oLat, oLon = loc.Lat, loc.Lon
		oNodeID = body.OriginNodeID
	} else {
		writeError(w, apiErr(400, "invalid_request", "originType must be home, clinic or node"))
		return
	}

	var earliest, latest *time.Time
	if body.EarliestCollection != "" {
		t, err := time.Parse(time.RFC3339, body.EarliestCollection)
		if err == nil {
			earliest = &t
		}
	}
	if body.LatestCollection != "" {
		t, err := time.Parse(time.RFC3339, body.LatestCollection)
		if err == nil {
			latest = &t
		}
	}
	if earliest != nil && latest != nil && latest.Before(*earliest) {
		writeError(w, apiErr(400, "invalid_deadline", "latest collection before earliest"))
		return
	}

	// Serviceability check (dry run equivalent) before persisting.
	res, err := a.store.checkServiceabilityFor(ctx, oLat, oLon, body.OriginType, body.SampleTypeID, deadline, st.RequiresCooled)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	if !res.Serviceable {
		writeError(w, apiErr(409, res.Reason, "request is not serviceable"))
		return
	}

	au := currentUser(r)
	var reqID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO requests (requester_id, origin_type, origin_lat, origin_lon, origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, already_sealed)
		VALUES ($1,$2,$3,$4,$5,now(),$6,$7,$8,$9,$10,$11,$12,$13,false) RETURNING id`,
		au.ID, body.OriginType, oLat, oLon, oNodeID, deadline, earliest, latest, body.SampleTypeID,
		st.ContainerType, st.TempMin, st.TempMax, pgJSONStr(st.Incompatible)).Scan(&reqID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}

	var sampleID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO samples (request_id, requester_id, sample_type_id, status, sealed, target_laboratory_id, origin_type, origin_lat, origin_lon, latest_lat, latest_lon, serviceability, serviceability_reason)
		VALUES ($1,$2,$3,'pending',false,$4,$5,$6,$7,$6,$7,'serviceable','serviceable') RETURNING id`,
		reqID, au.ID, body.SampleTypeID, res.TargetLabID, body.OriginType, oLat, oLon).Scan(&sampleID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}

	// Plan the journey: collection + transport legs to the lab.
	if err := a.store.planJourney(ctx, sampleID, body.OriginType, res.TargetLabID, res.EstArrival, deadline, st.RequiresCooled); err != nil {
		writeError(w, apiErr(409, "no_route", err.Error()))
		return
	}

	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "create_collection_request",
		ItemType: "request", ItemID: reqID, Outcome: "success"})
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "create_sample",
		ItemType: "sample", ItemID: sampleID, Outcome: "success"})

	samp, _ := a.store.sampleDetail(ctx, sampleID)
	writeData(w, 201, samp)
}

