	} else {
		writeError(w, apiErr(403, "not_handoff_party", "you are not a party to this handoff"))
		return
	}
	// Re-read confirmed state.
	_ = a.store.PG.QueryRow(ctx, `SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, body.HandoffID).Scan(&senderConf, &recvConf)
	if senderConf && recvConf {
		_, _ = a.store.PG.Exec(ctx, `UPDATE handoffs SET status='completed', confirmed_at=now() WHERE id=$1`, body.HandoffID)
		_, _ = a.store.PG.Exec(ctx, `UPDATE samples SET current_holder_id=$1 WHERE id=$2`, receiverID, sampleID)
		_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, fromAssignID)
		_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='accepted' WHERE id=$1`, toAssignID)
		// Release capacity for the completed leg.
		_, _ = a.store.PG.Exec(ctx, `DELETE FROM capacity_reservations WHERE assignment_id=$1`, fromAssignID)
		a.store.recordSampleEvent(ctx, sampleID, "custody_transferred", au.ID, map[string]interface{}{"from": senderID, "to": receiverID})
		// Offer next assignment after this one.
		var jid string
		_ = a.store.PG.QueryRow(ctx, `SELECT journey_id FROM assignments WHERE id=$1`, toAssignID).Scan(&jid)
		a.store.offerNextAssignment(ctx, jid, sampleID)
	}
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "confirm_handoff",
		ItemType: "handoff", ItemID: body.HandoffID, Outcome: "success"})
	writeData(w, 200, map[string]interface{}{"handoffId": body.HandoffID, "status": "completed"})
}

// handleRecordHandlingCheckpoint POST /api/record-handling-checkpoint
func (a *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		SampleID          string   `json:"sampleId"`
		ContainerType     string   `json:"containerType"`
		ObservedTempC     *float64 `json:"observedTemperatureC"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	var holderID *string
	_ = a.store.PG.QueryRow(ctx, `SELECT current_holder_id FROM samples WHERE id=$1`, body.SampleID).Scan(&holderID)
	if holderID == nil || *holderID != au.ID {
		writeError(w, apiErr(403, "not_current_holder", "you are not the current holder"))
		return
	}
	var tempMin, tempMax float64
	var requiredContainer string
	_ = a.store.PG.QueryRow(ctx, `SELECT st.temperature_min_c, st.temperature_max_c, st.container_type FROM samples s JOIN sample_types st ON st.id=s.sample_type_id WHERE s.id=$1`, body.SampleID).Scan(&tempMin, &tempMax, &requiredContainer)
	compliant := true
	reason := ""
	if body.ObservedTempC != nil {
		if *body.ObservedTempC < tempMin || *body.ObservedTempC > tempMax {
			compliant = false
			reason = "temperature_out_of_range"
		}
	}
	if body.ContainerType != "" && body.ContainerType != requiredContainer {
		compliant = false
		reason = "container_mismatch"
	}
	_, err := a.store.PG.Exec(ctx, `INSERT INTO checkpoints (sample_id, container_type, observed_temperature_c, compliant) VALUES ($1,$2,$3,$4)`,
		body.SampleID, body.ContainerType, body.ObservedTempC, compliant)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	if !compliant {
		_, _ = a.store.PG.Exec(ctx, `UPDATE samples SET exception=$1 WHERE id=$2`, pgJSONStr(map[string]interface{}{"reason": reason, "flaggedAt": time.Now().UTC().Format(time.RFC3339)}), body.SampleID)
		a.store.recordSampleEvent(ctx, body.SampleID, "exception", au.ID, map[string]interface{}{"reason": reason})
	}
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "record_handling_checkpoint",
		ItemType: "sample", ItemID: body.SampleID, Outcome: "success", Changes: map[string]interface{}{"compliant": compliant}})
	writeData(w, 200, map[string]interface{}{"sampleId": body.SampleID, "compliant": compliant, "reason": reason})
}

// handleConfirmLabReceipt POST /api/confirm-laboratory-receipt
func (a *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	if body.AssignmentID == "" && body.SampleID == "" {
		writeError(w, apiErr(400, "invalid_request", "assignmentId or sampleId required"))
		return
	}
	sampleID := body.SampleID
	if body.AssignmentID != "" {
		asn, err := a.store.getAssignment(ctx, body.AssignmentID)
		if err != nil {
			writeError(w, errNotFound)
			return
		}
		sampleID = asn.SampleID
		_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, body.AssignmentID)
	}
	_, err := a.store.PG.Exec(ctx, `UPDATE samples SET status='received', current_holder_id=$1 WHERE id=$2`, au.ID, sampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	// Release remaining capacity reservations.
	_, _ = a.store.PG.Exec(ctx, `DELETE FROM capacity_reservations WHERE sample_id=$1`, sampleID)
	a.store.recordSampleEvent(ctx, sampleID, "received_at_laboratory", au.ID, nil)
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "confirm_laboratory_receipt",
		ItemType: "sample", ItemID: sampleID, Outcome: "success"})
	samp, _ := a.store.sampleDetail(ctx, sampleID)
	writeData(w, 200, samp)
}

// handleRecordLabException POST /api/record-laboratory-exception
func (a *App) handleRecordLabException(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		SampleID string `json:"sampleId"`
		Reason   string `json:"reason"`
		Note     string `json:"note"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	_, err := a.store.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1 WHERE id=$2`,
		pgJSONStr(map[string]interface{}{"reason": body.Reason, "note": body.Note, "flaggedAt": time.Now().UTC().Format(time.RFC3339)}), body.SampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	a.store.recordSampleEvent(ctx, body.SampleID, "exception", au.ID, map[string]interface{}{"reason": body.Reason})
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "record_laboratory_exception",
		ItemType: "sample", ItemID: body.SampleID, Outcome: "success"})
	writeData(w, 200, map[string]interface{}{"sampleId": body.SampleID, "status": "exception"})
}

