package main

import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"go.mongodb.org/mongo-driver/bson"
)

// sampleDetail builds the full sample view for a requester/owner.
func (s *Store) sampleDetail(ctx context.Context, sampleID string) (map[string]interface{}, error) {
	var (
		id, status, originType                                           string
		sealed                                                           bool
		holderID, journeyID, labID                                       *string
		originLat, originLon, latestLat, latestLon                       *float64
		locRecordedAt                                                    *time.Time
		serviceability, serviceabilityReason                             string
		exceptionRaw                                                     []byte
		requesterID, sampleTypeID                                        string
	)
	err := s.PG.QueryRow(ctx, `SELECT id, requester_id, sample_type_id, status, sealed, current_holder_id, active_journey_id, target_laboratory_id,
		origin_type, origin_lat, origin_lon, latest_lat, latest_lon, location_recorded_at, serviceability, serviceability_reason, exception
		FROM samples WHERE id=$1`, sampleID).
		Scan(&id, &requesterID, &sampleTypeID, &status, &sealed, &holderID, &journeyID, &labID,
			&originType, &originLat, &originLon, &latestLat, &latestLon, &locRecordedAt, &serviceability, &serviceabilityReason, &exceptionRaw)
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{
		"sampleId":             id,
		"requesterId":          requesterID,
		"sampleTypeId":         sampleTypeID,
		"status":               status,
		"sealed":               sealed,
		"originType":           originType,
		"serviceability":       serviceability,
		"serviceabilityReason": serviceabilityReason,
	}
	if holderID != nil {
		out["currentHolderId"] = *holderID
	}
	if journeyID != nil {
		out["activeJourneyId"] = *journeyID
	}
	if labID != nil {
		out["targetLaboratoryId"] = *labID
	}
	if originLat != nil {
		out["originLat"] = *originLat
		out["originLon"] = *originLon
	}
	if latestLat != nil {
		out["latestLat"] = *latestLat
		out["latestLon"] = *latestLon
		out["currentLocation"] = map[string]interface{}{"latitude": *latestLat, "longitude": *latestLon}
	}
	stale := false
	if locRecordedAt != nil {
		out["locationRecordedAt"] = locRecordedAt.UTC().Format(time.RFC3339)
		if time.Since(*locRecordedAt) > 30*time.Minute {
			stale = true
		}
	}
	out["stale"] = stale
	if len(exceptionRaw) > 0 {
		var ex interface{}
		_ = json.Unmarshal(exceptionRaw, &ex)
		out["exception"] = ex
		out["exceptionFlag"] = true
	} else {
		out["exceptionFlag"] = false
	}
	// Add the status timeline (ordered) from Mongo.
	tl, _ := s.sampleTimeline(ctx, sampleID)
	out["statusHistory"] = tl
	return out, nil
}

// sampleTimeline returns the ordered list of status-change events for a sample.
func (s *Store) sampleTimeline(ctx context.Context, sampleID string) ([]map[string]interface{}, error) {
	cur, err := s.Mongo.Database("arena").Collection("sample_events").Find(ctx, bson.M{"sampleId": sampleID})
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var results []map[string]interface{}
	for cur.Next(ctx) {
		var doc map[string]interface{}
		if err := cur.Decode(&doc); err == nil {
			results = append(results, doc)
		}
	}
	if results == nil {
		results = []map[string]interface{}{}
	}
	return results, nil
}

// handleReadSampleState GET /api/read-sample-state/{sampleId}
func (a *App) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	role := currentRole(r)
	sampleID := pathID(r.URL.Path, "/api/read-sample-state/")
	if sampleID == "" {
		writeError(w, apiErr(400, "invalid_request", "sampleId required"))
		return
	}
	ctx := r.Context()
	// Access control: requester sees own; workers see assigned; admin/dispatcher see all.
	samp, err := a.store.sampleDetail(ctx, sampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	owner := samp["requesterId"]
	if role == "requester" && au.ID != owner {
		writeError(w, errForbidden)
		return
	}
	writeData(w, 200, samp)
}

// handleListRoleWork POST /api/list-role-work
func (a *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	role := currentRole(r)
	if role == "" {
		writeError(w, apiErr(400, "role_not_selected", "select an active role first"))
		return
	}
	ctx := r.Context()
	current := []interface{}{}
	past := []interface{}{}

	switch role {
	case "requester":
		current, past = a.store.requesterWork(ctx, au.ID)
	case "certified_collection_professional":
		current, past = a.store.workerWork(ctx, au.ID, "collection")
	case "relay_courier":
		current, past = a.store.workerWork(ctx, au.ID, "transport")
	case "node_handler":
		current, past = a.store.nodeWork(ctx, au.ID)
	case "laboratory_team":
		current, past = a.store.labWork(ctx, au.ID)
	case "dispatcher", "administrator":
		current, past = a.store.dispatcherWork(ctx, au.ID)
	}
	writeData(w, 200, map[string]interface{}{"current": current, "past": past, "role": role})
}

func (s *Store) requesterWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	cur := []interface{}{}
	past := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT id, status, origin_type, serviceability FROM samples WHERE requester_id=$1 AND status NOT IN ('received','cancelled','expired') ORDER BY created_at DESC`, userID)
	defer rows.Close()
	for rows.Next() {
		var id, status, ot, svc string
		_ = rows.Scan(&id, &status, &ot, &svc)
		cur = append(cur, map[string]interface{}{"sampleId": id, "status": status, "originType": ot, "serviceability": svc})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT id, status, origin_type FROM samples WHERE requester_id=$1 AND status IN ('received','cancelled','expired') ORDER BY created_at DESC`, userID)
	defer rows2.Close()
	for rows2.Next() {
		var id, status, ot string
		_ = rows2.Scan(&id, &status, &ot)
		past = append(past, map[string]interface{}{"sampleId": id, "status": status, "originType": ot})
	}
	return cur, past
}

func (s *Store) workerWork(ctx context.Context, userID, kind string) ([]interface{}, []interface{}) {
	cur := []interface{}{}
	past := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.status, a.sample_id FROM assignments a WHERE a.worker_id=$1 AND a.status IN ('offered','accepted','in_progress') ORDER BY a.created_at DESC`, userID)
	defer rows.Close()
	for rows.Next() {
		var id, knd, st, sid string
		_ = rows.Scan(&id, &knd, &st, &sid)
		cur = append(cur, map[string]interface{}{"assignmentId": id, "kind": knd, "status": st, "sampleId": sid})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.sample_id FROM assignments a WHERE a.worker_id=$1 AND a.status IN ('completed','declined') ORDER BY a.created_at DESC`, userID)
	defer rows2.Close()
	for rows2.Next() {
		var id, knd, sid string
		_ = rows2.Scan(&id, &knd, &sid)
		past = append(past, map[string]interface{}{"assignmentId": id, "kind": knd, "sampleId": sid})
	}
	return cur, past
}

func (s *Store) nodeWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	// Node handler: work for samples arriving/leaving their assigned node.
	var nodeID *string
	_ = s.PG.QueryRow(ctx, `SELECT assigned_location_id FROM users WHERE id=$1`, userID).Scan(&nodeID)
	cur := []interface{}{}
	past := []interface{}{}
	if nodeID == nil {
		return cur, past
	}
	rows, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.status, a.sample_id FROM assignments a WHERE a.node_id=$1 AND a.status IN ('offered','accepted','in_progress') ORDER BY a.created_at DESC`, *nodeID)
	defer rows.Close()
	for rows.Next() {
		var id, knd, st, sid string
		_ = rows.Scan(&id, &knd, &st, &sid)
		cur = append(cur, map[string]interface{}{"assignmentId": id, "kind": knd, "status": st, "sampleId": sid})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.sample_id FROM assignments a WHERE a.node_id=$1 AND a.status='completed' ORDER BY a.created_at DESC`, *nodeID)
	defer rows2.Close()
	for rows2.Next() {
		var id, knd, sid string
		_ = rows2.Scan(&id, &knd, &sid)
		past = append(past, map[string]interface{}{"assignmentId": id, "kind": knd, "sampleId": sid})
	}
	return cur, past
}

func (s *Store) labWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	var labID *string
	_ = s.PG.QueryRow(ctx, `SELECT assigned_location_id FROM users WHERE id=$1`, userID).Scan(&labID)
	cur := []interface{}{}
	past := []interface{}{}
	if labID == nil {
		return cur, past
	}
	rows, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.status, a.sample_id FROM assignments a WHERE a.laboratory_id=$1 AND a.status IN ('offered','accepted','in_progress') ORDER BY a.created_at DESC`, *labID)
	defer rows.Close()
	for rows.Next() {
		var id, knd, st, sid string
		_ = rows.Scan(&id, &knd, &st, &sid)
		cur = append(cur, map[string]interface{}{"assignmentId": id, "kind": knd, "status": st, "sampleId": sid})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.sample_id FROM assignments a WHERE a.laboratory_id=$1 AND a.status='completed' ORDER BY a.created_at DESC`, *labID)
	defer rows2.Close()
	for rows2.Next() {
		var id, knd, sid string
		_ = rows2.Scan(&id, &knd, &sid)
		past = append(past, map[string]interface{}{"assignmentId": id, "kind": knd, "sampleId": sid})
	}
	return cur, past
}

func (s *Store) dispatcherWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	cur := []interface{}{}
	past := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT id, status, serviceability FROM samples WHERE status NOT IN ('received','cancelled','expired') ORDER BY created_at DESC LIMIT 100`)
	defer rows.Close()
	for rows.Next() {
		var id, status, svc string
		_ = rows.Scan(&id, &status, &svc)
		cur = append(cur, map[string]interface{}{"sampleId": id, "status": status, "serviceability": svc})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT id, status FROM samples WHERE status IN ('received','cancelled','expired') ORDER BY created_at DESC LIMIT 100`)
	defer rows2.Close()
	for rows2.Next() {
		var id, status string
		_ = rows2.Scan(&id, &status)
		past = append(past, map[string]interface{}{"sampleId": id, "status": status})
	}
	return cur, past
}

// handleReadJourneyPlan POST /api/read-journey-plan
func (a *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var body struct{ SampleID string `json:"sampleId"` }
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	var journeyID string
	err := a.store.PG.QueryRow(ctx, `SELECT active_journey_id FROM samples WHERE id=$1`, body.SampleID).Scan(&journeyID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	jp, err := a.store.journeyPlan(ctx, journeyID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, jp)
}

func (s *Store) journeyPlan(ctx context.Context, journeyID string) (map[string]interface{}, error) {
	var id string
	var version int
	var routeMode, status string
	var estDelivery *time.Time
	var valid bool
	err := s.PG.QueryRow(ctx, `SELECT id, plan_version, route_mode, status, estimated_delivery_at, valid FROM journeys WHERE id=$1`, journeyID).
		Scan(&id, &version, &routeMode, &status, &estDelivery, &valid)
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{
		"journeyId": id, "planVersion": version, "routeMode": routeMode, "status": status, "valid": valid,
	}
	if estDelivery != nil {
		out["estimatedDeliveryAt"] = estDelivery.UTC().Format(time.RFC3339)
	}
	asns := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM assignments WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	defer rows.Close()
	for rows.Next() {
		var aid, kind, st, sid string
		var seq int
		var fromID, toID, wid *string
		_ = rows.Scan(&aid, &kind, &seq, &st, &fromID, &toID, &wid, &sid)
		entry := map[string]interface{}{"assignmentId": aid, "kind": kind, "sequence": seq, "status": st, "sampleId": sid}
		if fromID != nil {
			entry["fromLocationId"] = *fromID
		}
		if toID != nil {
			entry["toLocationId"] = *toID
		}
		if wid != nil {
			entry["workerId"] = *wid
		}
		asns = append(asns, entry)
	}
	out["assignments"] = asns
	return out, nil
}

// handleReadSampleLifecycle POST /api/read-sample-lifecycle
func (a *App) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var body struct{ SampleID string `json:"sampleId"` }
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	tl, err := a.store.sampleTimeline(ctx, body.SampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, map[string]interface{}{"sampleId": body.SampleID, "timeline": tl})
}

// handleReadOperationsState POST /api/read-operations-state (dispatcher/admin)
func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "dispatcher", "administrator"); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	samples := []interface{}{}
	rows, _ := a.store.PG.Query(ctx, `SELECT id, status, current_holder_id, latest_lat, latest_lon, location_recorded_at, exception FROM samples WHERE status NOT IN ('received','cancelled') ORDER BY created_at DESC LIMIT 200`)
	defer rows.Close()
	for rows.Next() {
		var id, status string
		var holderID *string
		var lat, lon *float64
		var locAt *time.Time
		var ex []byte
		_ = rows.Scan(&id, &status, &holderID, &lat, &lon, &locAt, &ex)
		entry := map[string]interface{}{"sampleId": id, "status": status}
		if holderID != nil {
			entry["currentHolderId"] = *holderID
		}
		if lat != nil {
			entry["latestLat"] = *lat
			entry["latestLon"] = *lon
		}
		stale := false
		if locAt != nil {
			entry["locationRecordedAt"] = locAt.UTC().Format(time.RFC3339)
			if time.Since(*locAt) > 30*time.Minute {
				stale = true
			}
		}
		entry["stale"] = stale
		entry["exceptionFlag"] = len(ex) > 0
		samples = append(samples, entry)
	}
	// workers
	workers := []interface{}{}
	wrows, _ := a.store.PG.Query(ctx, `SELECT u.id, u.username, u.roles, wl.lat, wl.lon, wl.available, wl.recorded_at FROM users u LEFT JOIN worker_locations wl ON wl.worker_id=u.id WHERE u.active=true`)
	defer wrows.Close()
	for wrows.Next() {
		var uid, uname string
		var roles []string
		var wlat, wlon *float64
		var avail *bool
		var rec *time.Time
		_ = wrows.Scan(&uid, &uname, &roles, &wlat, &wlon, &avail, &rec)
		entry := map[string]interface{}{"userId": uid, "username": uname, "roles": roles}
		if wlat != nil {
			entry["coordinate"] = map[string]interface{}{"latitude": *wlat, "longitude": *wlon}
