	)
	err := s.PG.QueryRow(ctx, `SELECT id, requester_id, sample_type_id, status, sealed, current_holder_id, active_journey_id, target_laboratory_id,
		origin_type, origin_lat, origin_lon, latest_lat, latest_lon, location_recorded_at, serviceability, serviceability_reason, exception
		FROM samples WHERE id=$1`, sampleID).
		Scan(&id, &requesterID, &sampleTypeID, &status, &sealed, &holderID, &journeyID, &labID,
			&originType, &originLat, &originLon, &latestLat, &latestLon, &locRecordedAt, &serviceability, &serviceabilityReason, &exceptionRaw)
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{
		"sampleId":             id,
		"requesterId":          requesterID,
		"sampleTypeId":         sampleTypeID,
		"status":               status,
		"sealed":               sealed,
		"originType":           originType,
		"serviceability":       serviceability,
		"serviceabilityReason": serviceabilityReason,
	}
