package main

import (
        "context"
        "fmt"
        "os"
        "path/filepath"

        "github.com/jackc/pgx/v5/pgxpool"
        "go.mongodb.org/mongo-driver/mongo"
        "go.mongodb.org/mongo-driver/mongo/options"
)

type Store struct {
        PG    *pgxpool.Pool
        Mongo *mongo.Client
        MongoDB *mongo.Database
}

func openStore(ctx context.Context, cfg *Config) (*Store, error) {
        pg, err := pgxpool.New(ctx, cfg.PostgresURL)
        if err != nil {
                return nil, fmt.Errorf("pg connect: %w", err)
        }
        if err := pg.Ping(ctx); err != nil {
                return nil, fmt.Errorf("pg ping: %w", err)
        }
        mc, err := mongo.Connect(ctx, options.Client().ApplyURI(cfg.MongoURI))
        if err != nil {
                return nil, fmt.Errorf("mongo connect: %w", err)
        }
        if err := mc.Ping(ctx, nil); err != nil {
                return nil, fmt.Errorf("mongo ping: %w", err)
        }
        return &Store{PG: pg, Mongo: mc, MongoDB: mc.Database("arena")}, nil
}

func (s *Store) Close() {
        if s.PG != nil {
                s.PG.Close()
        }
        if s.Mongo != nil {
                _ = s.Mongo.Disconnect(context.Background())
        }
}

func schemaSQL() (string, error) {
        // Try local schema.sql next to binary, else /workspace/backend/schema.sql
        for _, p := range []string{"schema.sql", "/workspace/backend/schema.sql"} {
                if b, err := os.ReadFile(p); err == nil {
                        return string(b), nil
                }
                if abs, err := filepath.Abs(p); err == nil {
                        if b, err := os.ReadFile(abs); err == nil {
                                return string(b), nil
                        }
                }
        }
        return "", fmt.Errorf("schema.sql not found")
}
