// recordSampleEvent appends an ordered lifecycle event for a sample.
func (s *Store) recordSampleEvent(ctx context.Context, sampleID, status, userID string, data map[string]interface{}) {
	seq, _ := s.nextSeq(ctx, "timeline")
	if data == nil {
		data = map[string]interface{}{}
	}
	data["actorId"] = userID
	s.appendTimeline(ctx, sampleID, seq, status, "", time.Now().UTC(), data)
}

// searchAudit returns audit entries filtered by itemType/itemId/action.
func (s *Store) searchAudit(ctx context.Context, itemType, itemID, action string, limit int) ([]map[string]interface{}, error) {
	filter := bson.M{}
	if itemType != "" {
		filter["item_type"] = itemType
	}
	if itemID != "" {
		filter["item_id"] = itemID
	}
	if action != "" {
		filter["action"] = action
	}
	if limit <= 0 || limit > 500 {
		limit = 100
	}
	cur, err := s.MongoDB.Collection("audit").Find(ctx, filter, options.Find().SetSort(bson.D{{Key: "timestamp", Value: -1}}).SetLimit(int64(limit)))
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var results []map[string]interface{}
	for cur.Next(ctx) {
		var doc map[string]interface{}
		if err := cur.Decode(&doc); err == nil {
			results = append(results, doc)
		}
	}
	if results == nil {
		results = []map[string]interface{}{}
	}
	return results, nil
}

