	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	tl, err := a.store.sampleTimeline(ctx, body.SampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, map[string]interface{}{"sampleId": body.SampleID, "timeline": tl})
}

// handleReadOperationsState POST /api/read-operations-state (dispatcher/admin)
func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "dispatcher", "administrator"); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	samples := []interface{}{}
	rows, _ := a.store.PG.Query(ctx, `SELECT id, status, current_holder_id, latest_lat, latest_lon, location_recorded_at, exception FROM samples WHERE status NOT IN ('received','cancelled') ORDER BY created_at DESC LIMIT 200`)
	defer rows.Close()
	for rows.Next() {
		var id, status string
		var holderID *string
		var lat, lon *float64
		var locAt *time.Time
		var ex []byte
		_ = rows.Scan(&id, &status, &holderID, &lat, &lon, &locAt, &ex)
		entry := map[string]interface{}{"sampleId": id, "status": status}
		if holderID != nil {
			entry["currentHolderId"] = *holderID
		}
		if lat != nil {
			entry["latestLat"] = *lat
			entry["latestLon"] = *lon
		}
		stale := false
		if locAt != nil {
			entry["locationRecordedAt"] = locAt.UTC().Format(time.RFC3339)
			if time.Since(*locAt) > 30*time.Minute {
				stale = true
			}
		}
		entry["stale"] = stale
		entry["exceptionFlag"] = len(ex) > 0
		samples = append(samples, entry)
	}
	// workers
	workers := []interface{}{}
	wrows, _ := a.store.PG.Query(ctx, `SELECT u.id, u.username, u.roles, wl.lat, wl.lon, wl.available, wl.recorded_at FROM users u LEFT JOIN worker_locations wl ON wl.worker_id=u.id WHERE u.active=true`)
	defer wrows.Close()
	for wrows.Next() {
		var uid, uname string
		var roles []string
		var wlat, wlon *float64
		var avail *bool
		var rec *time.Time
		_ = wrows.Scan(&uid, &uname, &roles, &wlat, &wlon, &avail, &rec)
		entry := map[string]interface{}{"userId": uid, "username": uname, "roles": roles}
		if wlat != nil {
			entry["coordinate"] = map[string]interface{}{"latitude": *wlat, "longitude": *wlon}
		}
		if avail != nil {
			entry["available"] = *avail
		}
		if rec != nil {
			entry["recordedAt"] = rec.UTC().Format(time.RFC3339)
		}
		workers = append(workers, entry)
	}
	writeData(w, 200, map[string]interface{}{"samples": samples, "workers": workers})
}

// handleReadServiceabilitySnapshot POST /api/read-serviceability-snapshot
func (a *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	snap, err := a.store.currentServiceability(r.Context())
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, snap)
}

// handleSearchAuditTrail POST /api/search-audit-trail
func (a *App) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		ItemType string `json:"itemType"`
		ItemID   string `json:"itemId"`
		Action   string `json:"action"`
		Limit    int    `json:"limit"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.Limit == 0 {
		body.Limit = 100
	}
	ctx := r.Context()
	entries, err := a.store.searchAudit(ctx, body.ItemType, body.ItemID, body.Action, body.Limit)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	writeData(w, 200, map[string]interface{}{"entries": entries})
}

// handleUIBootstrap GET /api/ui/bootstrap - returns config the SPA needs.
func (a *App) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	ctx := r.Context()
	stypes := []interface{}{}
	rows, _ := a.store.PG.Query(ctx, `SELECT id, name, requires_cooled_route, qualified_collector_required, required_qualification FROM sample_types ORDER BY name`)
	defer rows.Close()
	for rows.Next() {
		var id, name string
		var cooled, qual bool
		var rq *string
		_ = rows.Scan(&id, &name, &cooled, &qual, &rq)
		entry := map[string]interface{}{"sampleTypeId": id, "name": name, "requiresCooledRoute": cooled, "qualifiedCollectorRequired": qual}
		if rq != nil {
			entry["requiredQualification"] = *rq
		}
		stypes = append(stypes, entry)
	}
	locs := []interface{}{}
	lrows, _ := a.store.PG.Query(ctx, `SELECT id, name, lat, lon, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations ORDER BY name`)
	defer lrows.Close()
	for lrows.Next() {
		var id, name string
		var lat, lon float64
		var active, fc, ft, fh, fl bool
		_ = lrows.Scan(&id, &name, &lat, &lon, &active, &fc, &ft, &fh, &fl)
		locs = append(locs, map[string]interface{}{
			"locationId": id, "name": name, "latitude": lat, "longitude": lon, "active": active,
			"functions": map[string]interface{}{"collection_point": fc, "transfer_point": ft, "hub": fh, "laboratory": fl},
		})
	}
	writeData(w, 200, map[string]interface{}{
		"userId":    au.ID,
		"roles":     au.Roles,
		"activeRole": au.ActiveRole,
		"sampleTypes": stypes,
		"locations":  locs,
		"mapConfig": map[string]interface{}{
			"styleUrl": "/assets/maps/style.json",
		},
	})
}

// handleStreamEvents GET /api/events (Server-Sent Events stream of audit events)
func (a *App) handleStreamEvents(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, errInternal)
		return
	}
	// Send a heartbeat every 10s for up to 60s.
	for i := 0; i < 6; i++ {
		_, _ = w.Write([]byte(": heartbeat\n\n"))
		flusher.Flush()
		select {
		case <-r.Context().Done():
			return
		case <-time.After(10 * time.Second):
		}
	}
}

