	err = a.store.PG.QueryRow(ctx, `INSERT INTO samples (request_id, requester_id, sample_type_id, status, sealed, target_laboratory_id, origin_type, origin_lat, origin_lon, latest_lat, latest_lon, current_holder_id, serviceability)
		VALUES ('00000000-0000-0000-0000-000000000000',$1,$2,'in_transit',true,$3,$4,$5,$6,$5,$6,$7,'serviceable') RETURNING id`,
		au.ID, body.SampleTypeID, res.TargetLabID, body.OriginType, oLat, oLon, au.ID).Scan(&sampleID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}

	if err := a.store.planJourney(ctx, sampleID, body.OriginType, res.TargetLabID, res.EstArrival, deadline, st.RequiresCooled); err != nil {
		writeError(w, apiErr(409, "no_route", err.Error()))
		return
	}
	// Pre-sealed: skip collection assignment, the holder is the registering worker.
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "ingest_presealed",
		ItemType: "sample", ItemID: sampleID, Outcome: "success"})
	samp, _ := a.store.sampleDetail(ctx, sampleID)
	writeData(w, 201, samp)
}

// planJourney creates a journey with stops and assignments for a sample.
// originType "home"/"clinic" => needs a collection assignment first.
// "node" => transport legs from that node only.
func (s *Store) planJourney(ctx context.Context, sampleID, originType, labID string, estArrival, deadline time.Time, cooled bool) error {
	samp, err := s.sampleDetail(ctx, sampleID)
	if err != nil {
		return err
	}
	oLat, _ := samp["originLat"].(float64)
	oLon, _ := samp["originLon"].(float64)

	// Find the nearest active collection node to the origin.
	var srcNode string
	if originType == "node" {
		srcNode = samp["originNodeId"].(string)
	} else {
		srcNode, err = s.nearestCollectionNode(ctx, oLat, oLon)
		if err != nil {
			return err
		}
	}
	route, ok := s.findRoute(ctx, srcNode, labID, cooled)
	if !ok && srcNode != labID {
		return fmt.Errorf("no route to laboratory")
	}

	// Create the journey.
	var journeyID string
	sampleIDs := pgJSONStr([]string{sampleID})
	estStr := estArrival.UTC().Format(time.RFC3339)
	mode := "direct"
	if len(route) > 1 {
		mode = "multistop"
	}
	err = s.PG.QueryRow(ctx, `INSERT INTO journeys (plan_version, route_mode, status, estimated_delivery_at, sample_ids, valid)
		VALUES (1,$1,'planned',$2,$3,true) RETURNING id`, mode, estStr, sampleIDs).Scan(&journeyID)
	if err != nil {
		return err
	}
	_, _ = s.PG.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, journeyID, sampleID)

	seq := 0
	// Collection assignment (home/clinic only).
	if originType == "home" || originType == "clinic" {
		_, err = s.PG.Exec(ctx, `INSERT INTO assignments (journey_id, kind, sequence, status, from_location_id, to_location_id, sample_id, offer_expires_at)
			VALUES ($1,'collection',$2,'offered',NULL,$3,$4,$5)`,
			journeyID, seq, srcNode, sampleID, time.Now().Add(30*time.Minute))
		if err != nil {
			return err
		}
		seq++
	}

	// Transport legs.
	for _, leg := range route {
		var assignID string
		err = s.PG.QueryRow(ctx, `INSERT INTO assignments (journey_id, kind, sequence, status, from_location_id, to_location_id, sample_id, offer_expires_at)
			VALUES ($1,'transport',$2,'offered',$3,$4,$5,$6) RETURNING id`,
			journeyID, seq, leg.FromID, leg.ToID, sampleID, time.Now().Add(30*time.Minute)).Scan(&assignID)
		if err != nil {
			return err
		}
		// reserve capacity on the connection.
		_, _ = s.PG.Exec(ctx, `INSERT INTO capacity_reservations (resource_type, resource_id, journey_id, assignment_id, sample_id, regular_units, cooled_units)
			VALUES ('connection',$1,$2,$3,$4,$5,$6)`,
			leg.ConnID, journeyID, assignID, sampleID, boolToInt(!cooled), boolToInt(cooled))
		seq++
	}

	// Laboratory receipt assignment at the lab.
	_, err = s.PG.Exec(ctx, `INSERT INTO assignments (journey_id, kind, sequence, status, from_location_id, to_location_id, sample_id, laboratory_id, offer_expires_at)
		VALUES ($1,'laboratory_receipt',$2,'offered',$3,$3,$4,$5,$6)`,
		journeyID, seq, labID, sampleID, labID, time.Now().Add(30*time.Minute))
	if err != nil {
		return err
	}

	// Offer the first available assignment to an eligible worker (best-effort).
	s.offerNextAssignment(ctx, journeyID, sampleID)

	return nil
}

func (s *Store) nearestCollectionNode(ctx context.Context, lat, lon float64) (string, error) {
	rows, err := s.PG.Query(ctx, `SELECT id,lat,lon FROM locations WHERE active=true AND fn_collection_point=true`)
	if err != nil {
		return "", err
	}
	defer rows.Close()
	best := ""
	bestD := 1e9
	for rows.Next() {
		var id string
		var llat, llon float64
		if err := rows.Scan(&id, &llat, &llon); err != nil {
			continue
		}
		d := haversine(lat, lon, llat, llon)
		if d < bestD {
			bestD = d
			best = id
		}
	}
	if best == "" {
		return "", fmt.Errorf("no active collection node")
	}
	return best, nil
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

