		return
	}
	if !res.Serviceable {
		writeError(w, apiErr(409, res.Reason, "not serviceable"))
		return
	}

	au := currentUser(r)
	var sampleID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO samples (requester_id, sample_type_id, status, sealed, target_laboratory_id, origin_type, origin_lat, origin_lon, latest_lat, latest_lon, current_holder_id, serviceability)
		VALUES ($1,$2,'in_transit',true,$3,$4,$5,$6,$5,$6,$7,'serviceable') RETURNING id`,
		au.ID, body.SampleTypeID, res.TargetLabID, body.OriginType, oLat, oLon, au.ID).Scan(&sampleID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
