// expireOffers marks timed-out offers as declined and re-offers.
func (s *Store) expireOffers(ctx context.Context) {
        rows, err := s.PG.Query(ctx, `UPDATE assignments SET status='declined' WHERE status='offered' AND offer_expires_at < now() RETURNING id, journey_id, sample_id`)
        if err != nil {
                return
        }
        type rec struct{ id, jid, sid string }
        var recs []rec
        for rows.Next() {
                var r rec
                _ = rows.Scan(&r.id, &r.jid, &r.sid)
                recs = append(recs, r)
        }
        rows.Close()
        for _, r := range recs {
                s.offerNextAssignmentExcluding(ctx, r.jid, r.sid, r.id)
                s.audit(ctx, AuditEntry{Action: "offer_expired", ItemType: "assignment", ItemID: r.id, Outcome: "timeout"})
        }
}

// flagDeadlineExceptions marks samples past their deadline as exceptions/expired.
func (s *Store) flagDeadlineExceptions(ctx context.Context) {
        // Samples whose deadline has passed and not yet received.
        rows, err := s.PG.Query(ctx, `SELECT s.id FROM samples s JOIN requests r ON r.id=s.request_id
                WHERE s.status NOT IN ('received','cancelled','expired') AND r.delivery_deadline < now()`)
        if err != nil {
                return
        }
        var ids []string
        for rows.Next() {
                var id string
                _ = rows.Scan(&id)
                ids = append(ids, id)
        }
        rows.Close()
        for _, id := range ids {
                _, _ = s.PG.Exec(ctx, `UPDATE samples SET status='expired', exception=$1 WHERE id=$2`,
                        pgJSONStr(map[string]interface{}{"reason": "missed_delivery_deadline", "flaggedAt": time.Now().UTC().Format(time.RFC3339)}), id)
                s.recordSampleEvent(ctx, id, "expired", "", map[string]interface{}{"reason": "missed_delivery_deadline"})
                s.audit(ctx, AuditEntry{Action: "sample_expired", ItemType: "sample", ItemID: id, Outcome: "exception"})
        }
}

// handleCancelJourney POST /api/cancel-journey
func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
        if e := requireRole(r, "dispatcher", "administrator", "requester"); e != nil {
                writeError(w, e)
                return
        }
        var body struct {
                SampleID string `json:"sampleId"`
                Reason   string `json:"reason"`
        }
        if e := parseBody(r, &body); e != nil {
                writeError(w, e)
                return
        }
        ctx := r.Context()
        // Requester may only cancel their own.
        role := currentRole(r)
        if role == "requester" {
                var req string
                _ = a.store.PG.QueryRow(ctx, `SELECT requester_id FROM samples WHERE id=$1`, body.SampleID).Scan(&req)
                if req != currentUser(r).ID {
                        writeError(w, errForbidden)
                        return
                }
        }
        _, err := a.store.PG.Exec(ctx, `UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received','cancelled')`, body.SampleID)
        if err != nil {
                writeError(w, errNotFound)
                return
        }
        _, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE sample_id=$1 AND status NOT IN ('completed','cancelled')`, body.SampleID)
        _, _ = a.store.PG.Exec(ctx, `DELETE FROM capacity_reservations WHERE sample_id=$1`, body.SampleID)
        a.store.recordSampleEvent(ctx, body.SampleID, "cancelled", currentUser(r).ID, map[string]interface{}{"reason": body.Reason})
        a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: role, Action: "cancel_journey",
                ItemType: "sample", ItemID: body.SampleID, Outcome: "success"})
        writeData(w, 200, map[string]interface{}{"sampleId": body.SampleID, "status": "cancelled"})
}

