// handleReportDisruption POST /api/report-disruption
func (a *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
        if e := requireRole(r, "dispatcher", "administrator"); e != nil {
                writeError(w, e)
                return
        }
        var body struct {
                ResourceType string `json:"resourceType"`
                ResourceID   string `json:"resourceId"`
                Reason       string `json:"reason"`
        }
        if e := parseBody(r, &body); e != nil {
                writeError(w, e)
                return
        }
        ctx := r.Context()
        // Deactivate the resource and mark affected samples for replanning.
        switch body.ResourceType {
        case "worker":
                _, _ = a.store.PG.Exec(ctx, `UPDATE users SET active=false WHERE id=$1`, body.ResourceID)
        case "location":
                _, _ = a.store.PG.Exec(ctx, `UPDATE locations SET active=false WHERE id=$1`, body.ResourceID)
        case "connection":
                _, _ = a.store.PG.Exec(ctx, `UPDATE connections SET active=false WHERE id=$1`, body.ResourceID)
        }
        // Find affected samples (unfinished assignments using this resource).
        var affected []string
        rows, _ := a.store.PG.Query(ctx, `SELECT DISTINCT sample_id FROM assignments WHERE status IN ('offered','accepted','in_progress') AND (worker_id=$1 OR from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1)`, body.ResourceID)
        defer rows.Close()
        for rows.Next() {
                var sid string
                _ = rows.Scan(&sid)
                affected = append(affected, sid)
        }
        var dispID string
        _ = a.store.PG.QueryRow(ctx, `INSERT INTO disruptions (resource_type, resource_id, reason, affected_sample_ids, replan_status)
                VALUES ($1,$2,$3,$4,'required') RETURNING id`, body.ResourceType, body.ResourceID, body.Reason, pgJSONStr(affected)).Scan(&dispID)
        // Replan each affected sample's unfinished work (re-offer next assignment).
        for _, sid := range affected {
                var jid string
                _ = a.store.PG.QueryRow(ctx, `SELECT active_journey_id FROM samples WHERE id=$1`, sid).Scan(&jid)
                if jid != "" {
                        a.store.offerNextAssignment(ctx, jid, sid)
                }
        }
        a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "report_disruption",
                ItemType: "disruption", ItemID: dispID, Outcome: "success",
                Changes: map[string]interface{}{"resourceType": body.ResourceType, "affectedSamples": affected}})
        a.store.bumpNetworkRevision(ctx)
        writeData(w, 200, map[string]interface{}{"disruptionId": dispID, "affectedSamples": affected, "replanStatus": "required"})
}

