// pgJSON returns a []byte JSON encoding suitable for pgx JSONB columns.
func pgJSON(v interface{}) []byte {
        b, err := json.Marshal(v)
        if err != nil {
                return []byte("null")
        }
        return b
}

// pgJSONStr returns a string JSON encoding for pgx text/jsonb columns.
func pgJSONStr(v interface{}) string {
        b, err := json.Marshal(v)
        if err != nil {
                return "null"
        }
        return string(b)
}

func bcryptGenerate(pw []byte) ([]byte, error) {
        return bcrypt.GenerateFromPassword(pw, bcrypt.DefaultCost)
}

// contains reports whether s is in list.
func contains(list []string, s string) bool {
        for _, v := range list {
                if v == s {
                        return true
                }
        }
        return false
