        Timestamp  time.Time              `json:"timestamp" bson:"timestamp"`
        Outcome    string                 `json:"outcome" bson:"outcome"`
        Changes    map[string]interface{} `json:"changes,omitempty" bson:"changes,omitempty"`
        Detail     string                 `json:"detail,omitempty" bson:"detail,omitempty"`
}

// nextSeq returns a monotonically increasing sequence for the given collection.
func (s *Store) nextSeq(ctx context.Context, coll string) (int64, error) {
        // Find max
        var max int64
        cur, err := s.MongoDB.Collection(coll).Find(ctx, bson.D{}, options.Find().SetSort(bson.D{{Key: "sequence", Value: -1}}).SetLimit(1).SetProjection(bson.D{{Key: "sequence", Value: 1}}))
        if err != nil {
                return 0, err
        }
        defer cur.Close(ctx)
        for cur.Next(ctx) {
                var r struct {
                        Sequence int64 `bson:"sequence"`
                }
                if err := cur.Decode(&r); err == nil {
                        max = r.Sequence
                }
        }
        return max + 1, nil
}

func (s *Store) audit(ctx context.Context, e AuditEntry) {
        if e.Timestamp.IsZero() {
                e.Timestamp = time.Now().UTC()
        }
        seq, err := s.nextSeq(ctx, "audit")
        if err != nil {
                return
        }
        e.Sequence = seq
        _, _ = s.MongoDB.Collection("audit").InsertOne(ctx, e)
}

func (s *Store) appendTimeline(ctx context.Context, sampleID string, seq int64, status, detail string, at time.Time, data map[string]interface{}) {
        if at.IsZero() {
                at = time.Now().UTC()
        }
        doc := bson.M{
                "sample_id": sampleID,
                "sequence":  seq,
                "status":    status,
                "detail":    detail,
                "timestamp": at,
        }
        for k, v := range data {
                doc[k] = v
        }
        _, _ = s.MongoDB.Collection("timeline").InsertOne(ctx, doc)
}

// recordSampleEvent appends an ordered lifecycle event for a sample.
func (s *Store) recordSampleEvent(ctx context.Context, sampleID, status, userID string, data map[string]interface{}) {
        seq, _ := s.nextSeq(ctx, "timeline")
        if data == nil {
                data = map[string]interface{}{}
        }
        data["actorId"] = userID
        s.appendTimeline(ctx, sampleID, seq, status, "", time.Now().UTC(), data)
}

// searchAudit returns audit entries filtered by itemType/itemId/action.
func (s *Store) searchAudit(ctx context.Context, itemType, itemID, action string, limit int) ([]map[string]interface{}, error) {
        filter := bson.M{}
        if itemType != "" {
                filter["item_type"] = itemType
        }
        if itemID != "" {
                filter["item_id"] = itemID
        }
        if action != "" {
                filter["action"] = action
        }
        if limit <= 0 || limit > 500 {
                limit = 100
        }
        cur, err := s.MongoDB.Collection("audit").Find(ctx, filter, options.Find().SetSort(bson.D{{Key: "timestamp", Value: -1}}).SetLimit(int64(limit)))
        if err != nil {
                return nil, err
        }
        defer cur.Close(ctx)
        var results []map[string]interface{}
        for cur.Next(ctx) {
                var doc map[string]interface{}
                if err := cur.Decode(&doc); err == nil {
                        results = append(results, doc)
                }
        }
        if results == nil {
                results = []map[string]interface{}{}
        }
        return results, nil
}

type RealtimeEvent struct {
        Sequence  int64                  `json:"sequence" bson:"sequence"`
        Type      string                 `json:"type" bson:"type"`
        SampleID  string                 `json:"sample_id,omitempty" bson:"sample_id,omitempty"`
        UserID    string                 `json:"user_id,omitempty" bson:"user_id,omitempty"`
        Location  map[string]interface{} `json:"location,omitempty" bson:"location,omitempty"`
