package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

// handleCheckServiceability POST /api/check-serviceability (dry run)
func (a *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "requester", "administrator", "dispatcher"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		OriginType       string         `json:"originType"`
		Origin           *coordinateBody `json:"origin"`
		OriginNodeID     string         `json:"originNodeId"`
		SampleTypeID     string         `json:"sampleTypeId"`
		DeliveryDeadline string         `json:"deliveryDeadline"`
		RequestedAt      string         `json:"requestedAt"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.SampleTypeID == "" || body.DeliveryDeadline == "" || body.RequestedAt == "" {
		writeError(w, apiErr(400, "invalid_request", "origin, sampleTypeId, requestedAt, deliveryDeadline required"))
		return
	}
	deadline, err := time.Parse(time.RFC3339, body.DeliveryDeadline)
	if err != nil {
		writeError(w, apiErr(400, "invalid_request", "deliveryDeadline must be RFC3339"))
		return
	}
	ctx := r.Context()
	st, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "unknown sample type"))
		return
	}

	oLat, oLon, e := resolveOrigin(ctx, a.store, body.OriginType, body.Origin, body.OriginNodeID)
	if e != nil {
		writeError(w, e)
		return
	}

	res, err := a.store.checkServiceabilityFor(ctx, oLat, oLon, body.OriginType, body.SampleTypeID, deadline, st.RequiresCooled)
	if err != nil {
		writeError(w, errInternal)
		return
	}

	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "check_serviceability",
		ItemType: "serviceability", Outcome: "success",
		Changes: map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason}})

	resp := map[string]interface{}{
		"serviceable":          res.Serviceable,
		"reason":               res.Reason,
		"serviceabilityVersion": res.Version,
	}
	if res.TargetLabID != "" {
		resp["targetLaboratoryId"] = res.TargetLabID
	}
	if !res.EstArrival.IsZero() {
		resp["estimatedArrivalAt"] = res.EstArrival.UTC().Format(time.RFC3339)
	}
	writeData(w, 200, resp)
}

// resolveOrigin returns lat/lon for an origin spec shared by check/create/ingest.
func resolveOrigin(ctx context.Context, s *Store, originType string, coord *coordinateBody, nodeID string) (float64, float64, *errAPI) {
	switch originType {
	case "", "home", "clinic":
		if coord == nil {
			return 0, 0, apiErr(400, "invalid_coordinate", "origin coordinate required")
		}
		return coord.Latitude, coord.Longitude, nil
	case "node":
		loc, err := s.getLocation(ctx, nodeID)
		if err != nil {
			return 0, 0, apiErr(400, "invalid_request", "unknown origin node")
		}
		return loc.Lat, loc.Lon, nil
	default:
		return 0, 0, apiErr(400, "invalid_request", "originType must be home, clinic or node")
	}
}

// handleCreateCollectionRequest POST /api/create-collection-request
func (a *App) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "requester", "administrator"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		OriginType         string                 `json:"originType"`
		OriginCoordinate   map[string]float64     `json:"originCoordinate"`
		OriginNodeID       string                 `json:"originNodeId"`
		SampleTypeID       string                 `json:"sampleTypeId"`
		DeliveryDeadline   string                 `json:"deliveryDeadline"`
		EarliestCollection string                 `json:"earliestCollectionAt"`
		LatestCollection   string                 `json:"latestCollectionAt"`
		Notes              string                 `json:"notes"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.SampleTypeID == "" || body.DeliveryDeadline == "" || body.OriginType == "" {
		writeError(w, apiErr(400, "invalid_request", "originType, sampleTypeId, deliveryDeadline required"))
		return
	}
	deadline, err := time.Parse(time.RFC3339, body.DeliveryDeadline)
	if err != nil {
		writeError(w, apiErr(400, "invalid_deadline", "deliveryDeadline must be RFC3339"))
		return
	}
	ctx := r.Context()
	st, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "unknown sample type"))
		return
	}

	var oLat, oLon float64
	var oNodeID interface{}
	if body.OriginType == "home" || body.OriginType == "clinic" {
		if body.OriginCoordinate == nil {
			writeError(w, apiErr(400, "invalid_coordinate", "originCoordinate required"))
			return
		}
		oLat = body.OriginCoordinate["latitude"]
		oLon = body.OriginCoordinate["longitude"]
	} else if body.OriginType == "node" {
		loc, err := a.store.getLocation(ctx, body.OriginNodeID)
		if err != nil {
			writeError(w, apiErr(400, "invalid_request", "unknown origin node"))
			return
		}
		oLat, oLon = loc.Lat, loc.Lon
		oNodeID = body.OriginNodeID
	} else {
		writeError(w, apiErr(400, "invalid_request", "originType must be home, clinic or node"))
		return
	}

	var earliest, latest *time.Time
	if body.EarliestCollection != "" {
		t, err := time.Parse(time.RFC3339, body.EarliestCollection)
		if err == nil {
			earliest = &t
		}
	}
	if body.LatestCollection != "" {
		t, err := time.Parse(time.RFC3339, body.LatestCollection)
		if err == nil {
			latest = &t
		}
	}
	if earliest != nil && latest != nil && latest.Before(*earliest) {
		writeError(w, apiErr(400, "invalid_deadline", "latest collection before earliest"))
		return
	}

	// Serviceability check (dry run equivalent) before persisting.
	res, err := a.store.checkServiceabilityFor(ctx, oLat, oLon, body.OriginType, body.SampleTypeID, deadline, st.RequiresCooled)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	if !res.Serviceable {
		writeError(w, apiErr(409, res.Reason, "request is not serviceable"))
		return
	}

	au := currentUser(r)
	var reqID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO requests (requester_id, origin_type, origin_lat, origin_lon, origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, already_sealed)
		VALUES ($1,$2,$3,$4,$5,now(),$6,$7,$8,$9,$10,$11,$12,$13,false) RETURNING id`,
		au.ID, body.OriginType, oLat, oLon, oNodeID, deadline, earliest, latest, body.SampleTypeID,
		st.ContainerType, st.TempMin, st.TempMax, pgJSONStr(st.Incompatible)).Scan(&reqID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}

	var sampleID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO samples (request_id, requester_id, sample_type_id, status, sealed, target_laboratory_id, origin_type, origin_lat, origin_lon, latest_lat, latest_lon, delivery_deadline, serviceability, serviceability_reason)
		VALUES ($1,$2,$3,'pending',false,$4,$5,$6,$7,$6,$7,$8,'serviceable','serviceable') RETURNING id`,
		reqID, au.ID, body.SampleTypeID, res.TargetLabID, body.OriginType, oLat, oLon, body.DeliveryDeadline).Scan(&sampleID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}

	// Plan the journey: collection + transport legs to the lab.
	if err := a.store.planJourney(ctx, sampleID, body.OriginType, res.TargetLabID, res.EstArrival, deadline, st.RequiresCooled); err != nil {
		writeError(w, apiErr(409, "no_route", err.Error()))
		return
	}

	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "create_collection_request",
		ItemType: "request", ItemID: reqID, Outcome: "success"})
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "create_sample",
		ItemType: "sample", ItemID: sampleID, Outcome: "success"})

	samp, _ := a.store.sampleDetail(ctx, sampleID)
	writeData(w, 201, samp)
}

// handleIngestPresealed POST /api/ingest-presealed-sample
func (a *App) handleIngestPresealed(w http.ResponseWriter, r *http.Request) {
	allowed := []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}
	if e := requireRole(r, allowed...); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		OriginType       string             `json:"originType"`
		OriginNodeID     string             `json:"originNodeId"`
		OriginCoordinate map[string]float64 `json:"originCoordinate"`
		SampleTypeID     string             `json:"sampleTypeId"`
		DeliveryDeadline string             `json:"deliveryDeadline"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.OriginType == "home" {
		writeError(w, apiErr(400, "invalid_request", "presealed origin cannot be home"))
		return
	}
	if body.SampleTypeID == "" || body.DeliveryDeadline == "" {
		writeError(w, apiErr(400, "invalid_request", "sampleTypeId and deliveryDeadline required"))
		return
	}
	deadline, err := time.Parse(time.RFC3339, body.DeliveryDeadline)
	if err != nil {
		writeError(w, apiErr(400, "invalid_deadline", "deliveryDeadline must be RFC3339"))
		return
	}
	ctx := r.Context()
	st, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "unknown sample type"))
		return
	}
	var oLat, oLon float64
	if body.OriginType == "clinic" {
		oLat = body.OriginCoordinate["latitude"]
		oLon = body.OriginCoordinate["longitude"]
	} else if body.OriginType == "node" {
		loc, err := a.store.getLocation(ctx, body.OriginNodeID)
		if err != nil {
			writeError(w, apiErr(400, "invalid_request", "unknown origin node"))
			return
		}
		oLat, oLon = loc.Lat, loc.Lon
	} else {
		writeError(w, apiErr(400, "invalid_request", "originType must be clinic or node"))
		return
	}

	res, err := a.store.checkServiceabilityFor(ctx, oLat, oLon, body.OriginType, body.SampleTypeID, deadline, st.RequiresCooled)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	if !res.Serviceable {
		writeError(w, apiErr(409, res.Reason, "not serviceable"))
		return
	}

	au := currentUser(r)
	var sampleID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO samples (requester_id, sample_type_id, status, sealed, target_laboratory_id, origin_type, origin_lat, origin_lon, latest_lat, latest_lon, current_holder_id, serviceability)
		VALUES ($1,$2,'in_transit',true,$3,$4,$5,$6,$5,$6,$7,'serviceable') RETURNING id`,
		au.ID, body.SampleTypeID, res.TargetLabID, body.OriginType, oLat, oLon, au.ID).Scan(&sampleID)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}

	if err := a.store.planJourney(ctx, sampleID, body.OriginType, res.TargetLabID, res.EstArrival, deadline, st.RequiresCooled); err != nil {
		writeError(w, apiErr(409, "no_route", err.Error()))
		return
	}
	// Pre-sealed: skip collection assignment, the holder is the registering worker.
	a.store.audit(ctx, AuditEntry{UserID: au.ID, Role: currentRole(r), Action: "ingest_presealed",
		ItemType: "sample", ItemID: sampleID, Outcome: "success"})
	samp, _ := a.store.sampleDetail(ctx, sampleID)
	writeData(w, 201, samp)
}

// planJourney creates a journey with stops and assignments for a sample.
// originType "home"/"clinic" => needs a collection assignment first.
// "node" => transport legs from that node only.
func (s *Store) planJourney(ctx context.Context, sampleID, originType, labID string, estArrival, deadline time.Time, cooled bool) error {
	samp, err := s.sampleDetail(ctx, sampleID)
	if err != nil {
		return err
	}
	oLat, _ := samp["originLat"].(float64)
	oLon, _ := samp["originLon"].(float64)

	// Find the nearest active collection node to the origin.
	var srcNode string
	if originType == "node" {
		srcNode = samp["originNodeId"].(string)
	} else {
		srcNode, err = s.nearestCollectionNode(ctx, oLat, oLon)
		if err != nil {
			return err
		}
	}
	route, ok := s.findRoute(ctx, srcNode, labID, cooled)
	if !ok && srcNode != labID {
		return fmt.Errorf("no route to laboratory")
	}

	// Create the journey.
	var journeyID string
	sampleIDs := pgJSONStr([]string{sampleID})
	estStr := estArrival.UTC().Format(time.RFC3339)
	mode := "direct"
	if len(route) > 1 {
		mode = "multistop"
	}
	err = s.PG.QueryRow(ctx, `INSERT INTO journeys (plan_version, route_mode, status, estimated_delivery_at, sample_ids, valid)
		VALUES (1,$1,'planned',$2,$3,true) RETURNING id`, mode, estStr, sampleIDs).Scan(&journeyID)
	if err != nil {
		return err
	}
	_, _ = s.PG.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, journeyID, sampleID)

	seq := 0
	// Collection assignment (home/clinic only).
	if originType == "home" || originType == "clinic" {
		_, err = s.PG.Exec(ctx, `INSERT INTO assignments (journey_id, kind, sequence, status, from_location_id, to_location_id, sample_id, offer_expires_at)
			VALUES ($1,'collection',$2,'offered',NULL,$3,$4,$5)`,
			journeyID, seq, srcNode, sampleID, time.Now().Add(30*time.Minute))
		if err != nil {
			return err
		}
		seq++
	}

	// Transport legs.
	for _, leg := range route {
		var assignID string
		err = s.PG.QueryRow(ctx, `INSERT INTO assignments (journey_id, kind, sequence, status, from_location_id, to_location_id, sample_id, offer_expires_at)
			VALUES ($1,'transport',$2,'offered',$3,$4,$5,$6) RETURNING id`,
			journeyID, seq, leg.FromID, leg.ToID, sampleID, time.Now().Add(30*time.Minute)).Scan(&assignID)
		if err != nil {
			return err
		}
		// reserve capacity on the connection.
		_, _ = s.PG.Exec(ctx, `INSERT INTO capacity_reservations (resource_type, resource_id, journey_id, assignment_id, sample_id, regular_units, cooled_units)
			VALUES ('connection',$1,$2,$3,$4,$5,$6)`,
			leg.ConnID, journeyID, assignID, sampleID, boolToInt(!cooled), boolToInt(cooled))
		seq++
	}

	// Laboratory receipt assignment at the lab.
	_, err = s.PG.Exec(ctx, `INSERT INTO assignments (journey_id, kind, sequence, status, from_location_id, to_location_id, sample_id, laboratory_id, offer_expires_at)
		VALUES ($1,'laboratory_receipt',$2,'offered',$3,$3,$4,$5,$6)`,
		journeyID, seq, labID, sampleID, labID, time.Now().Add(30*time.Minute))
	if err != nil {
		return err
	}

	// Offer the first available assignment to an eligible worker (best-effort).
	s.offerNextAssignment(ctx, journeyID, sampleID)

	return nil
}

func (s *Store) nearestCollectionNode(ctx context.Context, lat, lon float64) (string, error) {
	rows, err := s.PG.Query(ctx, `SELECT id,lat,lon FROM locations WHERE active=true AND fn_collection_point=true`)
	if err != nil {
		return "", err
	}
	defer rows.Close()
	best := ""
	bestD := 1e9
	for rows.Next() {
		var id string
		var llat, llon float64
		if err := rows.Scan(&id, &llat, &llon); err != nil {
			continue
		}
		d := haversine(lat, lon, llat, llon)
		if d < bestD {
			bestD = d
			best = id
		}
	}
	if best == "" {
		return "", fmt.Errorf("no active collection node")
	}
	return best, nil
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

