func (s *Store) journeyPlan(ctx context.Context, journeyID string) (map[string]interface{}, error) {
	var id string
	var parentID *string
	var version int
	var routeMode, status string
	var estDelivery *time.Time
	var totalCost float64
	var sampleIDs []string
	var valid bool
	var replan *string
	err := s.PG.QueryRow(ctx, `SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, sample_ids, valid, replan_status FROM journeys WHERE id=$1`, journeyID).
		Scan(&id, &parentID, &version, &routeMode, &status, &estDelivery, &totalCost, &sampleIDs, &valid, &replan)
	if err != nil {
		return nil, err
	}
	if routeMode == "multistop" {
		routeMode = "multi_stop"
	}
	out := map[string]interface{}{
		"journeyId":      id,
		"planVersion":    version,
		"routeMode":      routeMode,
		"status":         status,
		"sampleIds":      sampleIDs,
		"orderedStops":   []interface{}{},
		"legs":           []interface{}{},
		"capacityUsed":   0,
		"capacityAvailable": 0,
	}
	if parentID != nil {
		out["parentJourneyId"] = *parentID
	}
	if estDelivery != nil {
		out["estimatedDeliveryAt"] = estDelivery.UTC().Format(time.RFC3339)
	}
	out["totalCostUnits"] = totalCost
	out["valid"] = valid
	if replan != nil {
		out["replanStatus"] = *replan
	}

	// Ordered stops.
	stops := []interface{}{}
	srows, _ := s.PG.Query(ctx, `SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at FROM stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	defer srows.Close()
	for srows.Next() {
		var stopID, locID, stopType string
		var seq int
		var estAt *time.Time
		var dwell int
		var compAt *time.Time
		_ = srows.Scan(&stopID, &locID, &stopType, &seq, &estAt, &dwell, &compAt)
		st := map[string]interface{}{
			"stopId":       stopID,
			"locationId":   locID,
			"stopType":     stopType,
			"sequence":     seq,
			"estimatedAt":  time.Now().UTC().Format(time.RFC3339),
			"dwellMinutes": dwell,
		}
		if estAt != nil {
			st["estimatedAt"] = estAt.UTC().Format(time.RFC3339)
		}
		if compAt != nil {
			st["completedAt"] = compAt.UTC().Format(time.RFC3339)
		}
		if loc, err := s.getLocation(ctx, locID); err == nil {
			st["coordinate"] = map[string]interface{}{"latitude": loc.Lat, "longitude": loc.Lon}
		}
		stops = append(stops, st)
	}
	out["orderedStops"] = stops

	// Legs (assignments) and derived ids.
	legs := []interface{}{}
	var collectionIDs, nodeIDs, labIDs, transportIDs []string
	var assignedWorkers []string
	rows, _ := s.PG.Query(ctx, `SELECT id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM assignments WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	defer rows.Close()
	for rows.Next() {
		var aid, kind, st, sid string
		var seq int
		var fromID, toID, wid *string
		_ = rows.Scan(&aid, &kind, &seq, &st, &fromID, &toID, &wid, &sid)
		leg := map[string]interface{}{"assignmentId": aid, "sequence": seq, "status": st}
		if fromID != nil {
			leg["fromLocationId"] = *fromID
		}
		if toID != nil {
			leg["toLocationId"] = *toID
		}
		if wid != nil {
			leg["workerId"] = *wid
			assignedWorkers = append(assignedWorkers, *wid)
		}
		if sid != "" {
			leg["sampleId"] = sid
		}
		legs = append(legs, leg)
		switch kind {
		case "collection":
			collectionIDs = append(collectionIDs, aid)
		case "node_handoff":
			nodeIDs = append(nodeIDs, aid)
		case "laboratory_receipt":
			labIDs = append(labIDs, aid)
		case "transport":
			transportIDs = append(transportIDs, aid)
		}
	}
	out["legs"] = legs
	out["assignedWorkerIds"] = assignedWorkers
	out["collectionAssignmentIds"] = collectionIDs
	if len(collectionIDs) > 0 {
		out["collectionAssignmentId"] = collectionIDs[0]
	}
	out["nodeAssignmentIds"] = nodeIDs
	out["laboratoryAssignmentIds"] = labIDs
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
	}
	if len(transportIDs) > 2 {
		out["middleTransportAssignmentId"] = transportIDs[1]
	}
	return out, nil
}

