func (s *Store) insertStop(ctx context.Context, journeyID, locationID, stopType string, seq int) {
	_, _ = s.PG.Exec(ctx, `INSERT INTO stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
		VALUES ($1,$2,$3,$4,now(),0)`, journeyID, locationID, stopType, seq)
}

