		OriginNodeID     string         `json:"originNodeId"`
		SampleTypeID     string         `json:"sampleTypeId"`
		DeliveryDeadline string         `json:"deliveryDeadline"`
		RequestedAt      string         `json:"requestedAt"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.SampleTypeID == "" || body.DeliveryDeadline == "" || body.RequestedAt == "" {
		writeError(w, apiErr(400, "invalid_request", "origin, sampleTypeId, requestedAt, deliveryDeadline required"))
		return
	}
	deadline, err := time.Parse(time.RFC3339, body.DeliveryDeadline)
	if err != nil {
		writeError(w, apiErr(400, "invalid_request", "deliveryDeadline must be RFC3339"))
		return
	}
	ctx := r.Context()
	st, err := a.store.getSampleType(ctx, body.SampleTypeID)
	if err != nil {
		writeError(w, apiErr(400, "invalid_handling_rules", "unknown sample type"))
		return
	}

	oLat, oLon, e := resolveOrigin(ctx, a.store, body.OriginType, body.Origin, body.OriginNodeID)
	if e != nil {
		writeError(w, e)
		return
	}

	res, err := a.store.checkServiceabilityFor(ctx, oLat, oLon, body.OriginType, body.SampleTypeID, deadline, st.RequiresCooled)
	if err != nil {
		writeError(w, errInternal)
		return
	}

	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "check_serviceability",
		ItemType: "serviceability", Outcome: "success",
		Changes: map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason}})

	resp := map[string]interface{}{
		"serviceable":          res.Serviceable,
		"reason":               res.Reason,
		"serviceabilityVersion": res.Version,
	}
	if res.TargetLabID != "" {
		resp["targetLaboratoryId"] = res.TargetLabID
	}
	if !res.EstArrival.IsZero() {
		resp["estimatedArrivalAt"] = res.EstArrival.UTC().Format(time.RFC3339)
	}
	writeData(w, 200, resp)
}

// resolveOrigin returns lat/lon for an origin spec shared by check/create/ingest.
func resolveOrigin(ctx context.Context, s *Store, originType string, coord *coordinateBody, nodeID string) (float64, float64, *errAPI) {
	switch originType {
	case "", "home", "clinic":
		if coord == nil {
			return 0, 0, apiErr(400, "invalid_coordinate", "origin coordinate required")
		}
		return coord.Latitude, coord.Longitude, nil
	case "node":
		loc, err := s.getLocation(ctx, nodeID)
		if err != nil {
			return 0, 0, apiErr(400, "invalid_request", "unknown origin node")
		}
		return loc.Lat, loc.Lon, nil
	default:
		return 0, 0, apiErr(400, "invalid_request", "originType must be home, clinic or node")
	}
}

// handleCreateCollectionRequest POST /api/create-collection-request
func (a *App) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
