		return
	}
	ctx := r.Context()
	tl, err := a.store.sampleTimeline(ctx, body.SampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	writeData(w, 200, map[string]interface{}{"sampleId": body.SampleID, "timeline": tl})
}

// handleReadOperationsState POST /api/read-operations-state (dispatcher/admin)
func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if e := requireRole(r, "dispatcher", "administrator"); e != nil {
		writeError(w, e)
		return
	}
	ctx := r.Context()
	samples := []interface{}{}
	rows, _ := a.store.PG.Query(ctx, `SELECT id, status, current_holder_id, latest_lat, latest_lon, location_recorded_at, exception FROM samples WHERE status NOT IN ('received','cancelled') ORDER BY created_at DESC LIMIT 200`)
	defer rows.Close()
	for rows.Next() {
		var id, status string
		var holderID *string
		var lat, lon *float64
		var locAt *time.Time
		var ex []byte
		_ = rows.Scan(&id, &status, &holderID, &lat, &lon, &locAt, &ex)
		entry := map[string]interface{}{"sampleId": id, "status": status}
		if holderID != nil {
			entry["currentHolderId"] = *holderID
		}
		if lat != nil {
			entry["latestLat"] = *lat
			entry["latestLon"] = *lon
		}
		stale := false
		if locAt != nil {
			entry["locationRecordedAt"] = locAt.UTC().Format(time.RFC3339)
			if time.Since(*locAt) > 30*time.Minute {
				stale = true
			}
		}
		entry["stale"] = stale
		entry["exceptionFlag"] = len(ex) > 0
		samples = append(samples, entry)
	}
	// workers
	workers := []interface{}{}
	wrows, _ := a.store.PG.Query(ctx, `SELECT u.id, u.username, u.roles, wl.lat, wl.lon, wl.available, wl.recorded_at FROM users u LEFT JOIN worker_locations wl ON wl.worker_id=u.id WHERE u.active=true`)
	defer wrows.Close()
	for wrows.Next() {
		var uid, uname string
		var roles []string
		var wlat, wlon *float64
		var avail *bool
		var rec *time.Time
		_ = wrows.Scan(&uid, &uname, &roles, &wlat, &wlon, &avail, &rec)
		entry := map[string]interface{}{"userId": uid, "username": uname, "roles": roles}
		if wlat != nil {
			entry["coordinate"] = map[string]interface{}{"latitude": *wlat, "longitude": *wlon}
		}
		if avail != nil {
			entry["available"] = *avail
		}
		if rec != nil {
			entry["recordedAt"] = rec.UTC().Format(time.RFC3339)
		}
		workers = append(workers, entry)
	}
	writeData(w, 200, map[string]interface{}{"samples": samples, "workers": workers})
}

