package main

import (
	"context"
	"net/http"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// sampleDetail builds the contract SampleState view for a sample.
func (s *Store) sampleDetail(ctx context.Context, sampleID string) (map[string]interface{}, error) {
	var (
		id, requesterID, requestID, sampleTypeID, status, originType string
		sealed                                                         bool
		holderID, journeyID, labID                                     *string
		originLat, originLon, latestLat, latestLon                     *float64
		locRecordedAt, requestedAt, deliveryDeadline                  *time.Time
		containerType                                                  string
		tempMin, tempMax                                               float64
		serviceability, serviceabilityReason                           string
		incompatible                                                    []string
	)
	err := s.PG.QueryRow(ctx, `SELECT s.id, s.requester_id, COALESCE(s.request_id::text,''), s.sample_type_id, s.status, s.sealed, s.current_holder_id, s.active_journey_id, s.target_laboratory_id,
		s.origin_type, s.origin_lat, s.origin_lon, s.latest_lat, s.latest_lon, s.location_recorded_at, s.container_type, s.temperature_min_c, s.temperature_max_c, s.serviceability, s.serviceability_reason, s.incompatible_sample_types,
		COALESCE(r.requested_at, s.created_at), COALESCE(r.delivery_deadline, s.delivery_deadline)
		FROM samples s LEFT JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&id, &requesterID, &requestID, &sampleTypeID, &status, &sealed, &holderID, &journeyID, &labID,
			&originType, &originLat, &originLon, &latestLat, &latestLon, &locRecordedAt, &containerType, &tempMin, &tempMax, &serviceability, &serviceabilityReason, &incompatible,
			&requestedAt, &deliveryDeadline)
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{
		"sampleId":               id,
		"requestId":              requestID,
		"requesterId":            requesterID,
		"sampleTypeId":           sampleTypeID,
		"originType":             originType,
		"containerType":          containerType,
		"temperatureMinC":        tempMin,
		"temperatureMaxC":        tempMax,
		"incompatibleSampleTypes": incompatible,
		"serviceability":         serviceability,
		"activeAssignmentIds":    s.activeAssignmentIDs(ctx, derefStr(journeyID)),
		"state":                  map[string]interface{}{"status": status},
		"timeline":               mustTimeline(s, ctx, id),
		"locationStale":          false,
	}
	if originLat != nil {
		out["origin"] = map[string]interface{}{"latitude": *originLat, "longitude": *originLon}
	} else {
		out["origin"] = map[string]interface{}{"latitude": 0.0, "longitude": 0.0}
	}
	if requestedAt != nil {
		out["requestedAt"] = requestedAt.UTC().Format(time.RFC3339)
	}
	if deliveryDeadline != nil {
		out["deliveryDeadline"] = deliveryDeadline.UTC().Format(time.RFC3339)
	}
	if serviceabilityReason != "" {
		out["serviceabilityReason"] = serviceabilityReason
	}
	if holderID != nil {
		out["currentHolderId"] = *holderID
	}
	if journeyID != nil {
		out["activeJourneyId"] = *journeyID
	}
	if labID != nil {
		out["targetLaboratoryId"] = *labID
	}
	if latestLat != nil {
		out["latestLocation"] = map[string]interface{}{"latitude": *latestLat, "longitude": *latestLon}
	}
	if locRecordedAt != nil {
		out["locationRecordedAt"] = locRecordedAt.UTC().Format(time.RFC3339)
		if time.Since(*locRecordedAt) > 30*time.Minute {
			out["locationStale"] = true
		}
	}
	return out, nil
}

func derefStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func mustTimeline(s *Store, ctx context.Context, sampleID string) []interface{} {
	tl, _ := s.sampleTimeline(ctx, sampleID)
	return tl
}

// sampleTimeline returns the ordered list of status-change events for a sample.
func (s *Store) sampleTimeline(ctx context.Context, sampleID string) ([]map[string]interface{}, error) {
	cur, err := s.MongoDB.Collection("timeline").Find(ctx, bson.M{"sample_id": sampleID}, options.Find().SetSort(bson.D{{Key: "sequence", Value: 1}}))
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var results []map[string]interface{}
	for cur.Next(ctx) {
		var doc map[string]interface{}
		if err := cur.Decode(&doc); err == nil {
			results = append(results, doc)
		}
	}
	if results == nil {
		results = []map[string]interface{}{}
	}
	return results, nil
}

// handleReadSampleState GET /api/read-sample-state/{sampleId}
func (a *App) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	role := currentRole(r)
	sampleID := pathID(r.URL.Path, "/api/read-sample-state/")
	if sampleID == "" {
		writeError(w, apiErr(400, "invalid_request", "sampleId required"))
		return
	}
	ctx := r.Context()
	// Access control: requester sees own; workers see assigned; admin/dispatcher see all.
	samp, err := a.store.sampleDetail(ctx, sampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	owner := samp["requesterId"]
	if role == "requester" && au.ID != owner {
		writeError(w, errForbidden)
		return
	}
	writeData(w, 200, samp)
}

// handleListRoleWork POST /api/list-role-work
func (a *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	role := currentRole(r)
	if role == "" {
		writeError(w, apiErr(400, "role_not_selected", "select an active role first"))
		return
	}
	ctx := r.Context()
	current := []interface{}{}
	past := []interface{}{}

	switch role {
	case "requester":
		current, past = a.store.requesterWork(ctx, au.ID)
	case "collection_professional":
		current, past = a.store.workerWork(ctx, au.ID, "collection")
	case "delivery_partner":
		current, past = a.store.workerWork(ctx, au.ID, "transport")
	case "node_handler":
		current, past = a.store.nodeWork(ctx, au.ID)
	case "laboratory_team":
		current, past = a.store.labWork(ctx, au.ID)
	case "dispatcher", "administrator":
		current, past = a.store.dispatcherWork(ctx, au.ID)
	}
	writeData(w, 200, map[string]interface{}{"current": current, "past": past, "role": role})
}

func (s *Store) requesterWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	cur := []interface{}{}
	past := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT id, status, origin_type, serviceability FROM samples WHERE requester_id=$1 AND status NOT IN ('received','cancelled','expired') ORDER BY created_at DESC`, userID)
	defer rows.Close()
	for rows.Next() {
		var id, status, ot, svc string
		_ = rows.Scan(&id, &status, &ot, &svc)
		cur = append(cur, map[string]interface{}{"sampleId": id, "status": status, "originType": ot, "serviceability": svc})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT id, status, origin_type FROM samples WHERE requester_id=$1 AND status IN ('received','cancelled','expired') ORDER BY created_at DESC`, userID)
	defer rows2.Close()
	for rows2.Next() {
		var id, status, ot string
		_ = rows2.Scan(&id, &status, &ot)
		past = append(past, map[string]interface{}{"sampleId": id, "status": status, "originType": ot})
	}
	return cur, past
}

func (s *Store) workerWork(ctx context.Context, userID, kind string) ([]interface{}, []interface{}) {
	cur := []interface{}{}
	past := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.status, a.sample_id FROM assignments a WHERE a.worker_id=$1 AND a.status IN ('offered','accepted','in_progress') ORDER BY a.created_at DESC`, userID)
	defer rows.Close()
