		past = append(past, map[string]interface{}{"assignmentId": id, "kind": knd, "sampleId": sid})
	}
	return cur, past
}

func (s *Store) nodeWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	// Node handler: work for samples arriving/leaving their assigned node.
	var nodeID *string
	_ = s.PG.QueryRow(ctx, `SELECT assigned_location_id FROM users WHERE id=$1`, userID).Scan(&nodeID)
	cur := []interface{}{}
	past := []interface{}{}
	if nodeID == nil {
		return cur, past
	}
	rows, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.status, a.sample_id FROM assignments a WHERE a.node_id=$1 AND a.status IN ('offered','accepted','in_progress') ORDER BY a.created_at DESC`, *nodeID)
	defer rows.Close()
	for rows.Next() {
		var id, knd, st, sid string
		_ = rows.Scan(&id, &knd, &st, &sid)
		cur = append(cur, map[string]interface{}{"assignmentId": id, "kind": knd, "status": st, "sampleId": sid})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.sample_id FROM assignments a WHERE a.node_id=$1 AND a.status='completed' ORDER BY a.created_at DESC`, *nodeID)
	defer rows2.Close()
	for rows2.Next() {
		var id, knd, sid string
		_ = rows2.Scan(&id, &knd, &sid)
		past = append(past, map[string]interface{}{"assignmentId": id, "kind": knd, "sampleId": sid})
	}
	return cur, past
}

func (s *Store) labWork(ctx context.Context, userID string) ([]interface{}, []interface{}) {
	var labID *string
	_ = s.PG.QueryRow(ctx, `SELECT assigned_location_id FROM users WHERE id=$1`, userID).Scan(&labID)
	cur := []interface{}{}
	past := []interface{}{}
	if labID == nil {
		return cur, past
	}
	rows, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.status, a.sample_id FROM assignments a WHERE a.laboratory_id=$1 AND a.status IN ('offered','accepted','in_progress') ORDER BY a.created_at DESC`, *labID)
	defer rows.Close()
	for rows.Next() {
		var id, knd, st, sid string
		_ = rows.Scan(&id, &knd, &st, &sid)
		cur = append(cur, map[string]interface{}{"assignmentId": id, "kind": knd, "status": st, "sampleId": sid})
	}
	rows2, _ := s.PG.Query(ctx, `SELECT a.id, a.kind, a.sample_id FROM assignments a WHERE a.laboratory_id=$1 AND a.status='completed' ORDER BY a.created_at DESC`, *labID)
	defer rows2.Close()
	for rows2.Next() {
		var id, knd, sid string
		_ = rows2.Scan(&id, &knd, &sid)
		past = append(past, map[string]interface{}{"assignmentId": id, "kind": knd, "sampleId": sid})
