type AuditEntry struct {
	AuditID     string                 `json:"auditId" bson:"auditId"`
	ActorID     string                 `json:"actorId" bson:"actorId"`
	Role        string                 `json:"role" bson:"role"`
	ActorRole   string                 `json:"actorRole" bson:"actorRole"`
	Action      string                 `json:"action" bson:"action"`
	EntityType  string                 `json:"entityType" bson:"entityType"`
	EntityID    string                 `json:"entityId" bson:"entityId"`
	Success     bool                   `json:"success" bson:"success"`
	OccurredAt  time.Time              `json:"occurredAt" bson:"occurredAt"`
	Details     map[string]interface{} `json:"details" bson:"details"`
}

// nextSeq returns a monotonically increasing sequence for the given collection.
func (s *Store) nextSeq(ctx context.Context, coll string) (int64, error) {
	// Find max
	var max int64
	cur, err := s.MongoDB.Collection(coll).Find(ctx, bson.D{}, options.Find().SetSort(bson.D{{Key: "sequence", Value: -1}}).SetLimit(1).SetProjection(bson.D{{Key: "sequence", Value: 1}}))
	if err != nil {
		return 0, err
	}
	defer cur.Close(ctx)
	for cur.Next(ctx) {
		var r struct {
			Sequence int64 `bson:"sequence"`
		}
		if err := cur.Decode(&r); err == nil {
			max = r.Sequence
		}
	}
	return max + 1, nil
}

