package main

import (
	"context"
	"fmt"
	"net/http"
	"time"
)

// assignmentRow represents an assignment record.
type assignmentRow struct {
	ID            string
	JourneyID     string
	Kind          string
	Sequence      int
	Status        string
	FromLocID     *string
	ToLocID       *string
	WorkerID      *string
	SampleID      string
	NodeID        *string
	LabID         *string
	OfferExpires  *time.Time
	DeclinedBy    []string
}

func (s *Store) getAssignment(ctx context.Context, id string) (*assignmentRow, error) {
	var a assignmentRow
	err := s.PG.QueryRow(ctx, `SELECT id,journey_id,kind,sequence,status,from_location_id,to_location_id,worker_id,sample_id,node_id,laboratory_id,offer_expires_at,declined_by
		FROM assignments WHERE id=$1`, id).
		Scan(&a.ID, &a.JourneyID, &a.Kind, &a.Sequence, &a.Status, &a.FromLocID, &a.ToLocID, &a.WorkerID, &a.SampleID, &a.NodeID, &a.LabID, &a.OfferExpires, &a.DeclinedBy)
	if err != nil {
		return nil, err
	}
	return &a, nil
}

// offerNextAssignment offers the earliest 'offered' assignment in the journey to
// the next eligible worker (best-effort, non-blocking). If none eligible, the
// assignment stays 'offered' and will be flagged as an exception after timeout.
func (s *Store) offerNextAssignment(ctx context.Context, journeyID, sampleID string) {
	var assignID, kind string
	var seq int
	err := s.PG.QueryRow(ctx, `SELECT id,kind,sequence FROM assignments WHERE journey_id=$1 AND status='offered' ORDER BY sequence LIMIT 1`, journeyID).Scan(&assignID, &kind, &seq)
	if err != nil {
		return
	}
	workerID, ok := s.findEligibleWorker(ctx, kind, assignID, sampleID)
	if !ok {
		// no eligible worker now; leave offered; periodic task will flag.
		return
	}
	_, _ = s.PG.Exec(ctx, `UPDATE assignments SET worker_id=$1, offer_expires_at=$2 WHERE id=$3`, workerID, time.Now().Add(15*time.Minute), assignID)
	s.audit(ctx, AuditEntry{Action: "offer_assignment", EntityType: "assignment", EntityID: assignID,
		ActorID: workerID, Success: true, Details: map[string]interface{}{"kind": kind, "sequence": seq}})
}

// findEligibleWorker returns the user id of the next eligible worker for a kind.
// Considers workload and recent declines.
func (s *Store) findEligibleWorker(ctx context.Context, kind, assignID, sampleID string) (string, bool) {
	var nodeID, labID *string
	_ = s.PG.QueryRow(ctx, `SELECT node_id, laboratory_id FROM assignments WHERE id=$1`, assignID).Scan(&nodeID, &labID)

	var role string
	switch kind {
	case "collection":
		role = "collection_professional"
	case "transport":
		role = "delivery_partner"
	case "node_handoff":
		role = "node_handler"
	case "laboratory_receipt":
		role = "laboratory_team"
	default:
		role = "delivery_partner"
	}

	q := `SELECT u.id FROM users u
		WHERE u.active=true AND u.roles @> $1::jsonb`
	args := []interface{}{pgJSONStr([]string{role})}
	if nodeID != nil {
		q += ` AND u.assigned_location_id=$2`
		args = append(args, *nodeID)
	} else if labID != nil {
		q += ` AND u.assigned_location_id=$2`
		args = append(args, *labID)
	}
	q += ` ORDER BY (SELECT count(*) FROM assignments a WHERE a.worker_id=u.id AND a.status IN ('offered','accepted','in_progress')) ASC, u.created_at ASC LIMIT 1`

	var workerID string
	err := s.PG.QueryRow(ctx, q, args...).Scan(&workerID)
	if err != nil {
		return "", false
	}
	return workerID, true
}

// handleAcceptAssignment POST /api/accept-assignment
func (a *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		AssignmentID  string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	if body.AssignmentID == "" {
		writeError(w, apiErr(400, "invalid_json", "assignmentId required"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "accept_assignment", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	asn, err := a.store.getAssignment(ctx, body.AssignmentID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	if asn.Status == "completed" || asn.Status == "cancelled" {
		writeError(w, apiErr(409, "assignment_inactive", "assignment is "+asn.Status))
		return
	}
	if asn.Status == "accepted" {
		if asn.WorkerID == nil || *asn.WorkerID != au.ID {
			writeError(w, apiErr(409, "assignment_taken", "assignment taken by another worker"))
			return
		}
	}
	if asn.WorkerID == nil || *asn.WorkerID != au.ID {
		writeError(w, apiErr(409, "offer_not_available", "assignment was not offered to you"))
		return
	}
	// Role/eligibility match check.
	if roleForKind(asn.Kind) != currentRole(r) {
		writeError(w, apiErr(400, "ineligible_worker", "role not eligible for this assignment kind"))
		return
	}
	if asn.Status != "offered" {
		writeError(w, apiErr(409, "offer_not_offered", "assignment is "+asn.Status))
		return
	}
	_, err = a.store.PG.Exec(ctx, `UPDATE assignments SET status='accepted' WHERE id=$1`, body.AssignmentID)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "accept_assignment",
		EntityType: "assignment", EntityID: body.AssignmentID, Success: true})
	resp := map[string]interface{}{"assignmentId": body.AssignmentID, "workerId": au.ID, "status": "accepted"}
	writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "accept_assignment")
}

// handleDeclineAssignment POST /api/decline-assignment
func (a *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		AssignmentID  string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
		Reason        string `json:"reason"`
		DeclinedAt    string `json:"declinedAt"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	if body.AssignmentID == "" {
		writeError(w, apiErr(400, "invalid_json", "assignmentId required"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "decline_assignment", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	asn, err := a.store.getAssignment(ctx, body.AssignmentID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	if asn.WorkerID == nil || *asn.WorkerID != au.ID {
		writeError(w, apiErr(409, "offer_not_available", "assignment was not offered to you"))
		return
	}
	_, err = a.store.PG.Exec(ctx, `UPDATE assignments SET declined_by = declined_by || $1::jsonb, worker_id=NULL, status='offered' WHERE id=$2`,
		pgJSONStr([]string{au.ID}), body.AssignmentID)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	declinedAt := body.DeclinedAt
	if declinedAt == "" {
		declinedAt = time.Now().UTC().Format(time.RFC3339)
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "decline_assignment",
		EntityType: "assignment", EntityID: body.AssignmentID, Success: true, Details: map[string]interface{}{"reason": body.Reason}})
	reoffered := a.store.offerNextAssignmentExcluding(ctx, asn.JourneyID, asn.SampleID, asn.ID)
	resp := map[string]interface{}{"assignmentId": body.AssignmentID, "status": "pending", "declinedBy": au.ID, "declinedAt": declinedAt}
	if reoffered != "" {
		resp["reofferedTo"] = reoffered
	}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "decline_assignment")
}

func (s *Store) offerNextAssignmentExcluding(ctx context.Context, journeyID, sampleID, assignID string) string {
	var kind, nodeID, labID *string
	_ = s.PG.QueryRow(ctx, `SELECT kind, node_id, laboratory_id FROM assignments WHERE id=$1`, assignID).Scan(&kind, &nodeID, &labID)
	role := roleForKind(*kind)
	q := `SELECT u.id FROM users u WHERE u.active=true AND u.roles @> $1::jsonb`
	args := []interface{}{pgJSONStr([]string{role})}
	if nodeID != nil {
		q += ` AND u.assigned_location_id=$2`
		args = append(args, *nodeID)
	} else if labID != nil {
		q += ` AND u.assigned_location_id=$2`
		args = append(args, *labID)
	}
	q += ` ORDER BY (SELECT count(*) FROM assignments a WHERE a.worker_id=u.id AND a.status IN ('offered','accepted','in_progress')) ASC, u.created_at ASC LIMIT 1`
	var wid string
	if err := s.PG.QueryRow(ctx, q, args...).Scan(&wid); err == nil {
		_, _ = s.PG.Exec(ctx, `UPDATE assignments SET worker_id=$1, offer_expires_at=$2 WHERE id=$3`, wid, time.Now().Add(15*time.Minute), assignID)
		s.audit(ctx, AuditEntry{Action: "offer_assignment", EntityType: "assignment", EntityID: assignID, ActorID: wid, Success: true})
		return wid
	}
	return ""
}

func roleForKind(kind string) string {
	switch kind {
	case "collection":
		return "collection_professional"
	case "transport":
		return "delivery_partner"
	case "node_handoff":
		return "node_handler"
	case "laboratory_receipt":
		return "laboratory_team"
	}
	return "delivery_partner"
}

// handleCollectAndSeal POST /api/collect-and-seal-sample
func (a *App) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		SampleID    string   `json:"sampleId"`
		AssignmentID string   `json:"assignmentId"`
		CollectedAt  string   `json:"collectedAt"`
		ContainerType string  `json:"containerType"`
		Temperature  *float64 `json:"observedTemperatureC"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	if _, e := parseTimeField(body.CollectedAt); e != nil {
		writeError(w, apiErr(400, "invalid_time", "collectedAt invalid"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "collect_and_seal_sample", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	asn, err := a.store.getAssignment(ctx, body.AssignmentID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	if asn.SampleID != body.SampleID {
		writeError(w, apiErr(404, "not_found", "sample/assignment mismatch"))
		return
	}
	if asn.Status == "completed" || asn.Status == "cancelled" {
		writeError(w, apiErr(409, "assignment_inactive", "assignment is "+asn.Status))
		return
	}
	if asn.WorkerID == nil || *asn.WorkerID != au.ID {
		writeError(w, apiErr(403, "forbidden", "not your assignment"))
		return
	}
	if asn.Kind != "collection" {
		writeError(w, apiErr(409, "collection_not_ready", "expected collection assignment"))
		return
	}
	// Verify qualification matches the sample type.
	var stName, reqQual string
	var sealed bool
	_ = a.store.PG.QueryRow(ctx, `SELECT st.name, st.required_qualification, s.sealed FROM samples s JOIN sample_types st ON st.id=s.sample_type_id WHERE s.id=$1`, asn.SampleID).Scan(&stName, &reqQual, &sealed)
	if sealed {
		writeError(w, apiErr(409, "invalid_sample_state", "sample already sealed"))
		return
	}
	if reqQual != "" && !contains(au.Qualifications, reqQual) {
		writeError(w, apiErr(409, "certification_inactive", "not qualified for "+stName))
		return
	}
	// Collection window check.
	colAt, _ := parseTimeField(body.CollectedAt)
	var winStart, winEnd *time.Time
	_ = a.store.PG.QueryRow(ctx, `SELECT collection_window_start, collection_window_end FROM requests WHERE id=(SELECT request_id FROM samples WHERE id=$1)`, asn.SampleID).Scan(&winStart, &winEnd)
	if winStart != nil && colAt.Before(*winStart) || winEnd != nil && colAt.After(*winEnd) {
		writeError(w, apiErr(409, "outside_collection_window", "collectedAt outside collection window"))
		return
	}
	// Compliance check against sample type temp range.
	compliant := true
	if body.Temperature != nil {
		var tempMin, tempMax *float64
		_ = a.store.PG.QueryRow(ctx, `SELECT temp_min, temp_max FROM sample_types WHERE id=(SELECT sample_type_id FROM samples WHERE id=$1)`, asn.SampleID).Scan(&tempMin, &tempMax)
		if tempMin != nil && *body.Temperature < *tempMin {
			compliant = false
		}
		if tempMax != nil && *body.Temperature > *tempMax {
			compliant = false
		}
	}
	if !compliant {
		a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "collect_and_seal",
			EntityType: "sample", EntityID: asn.SampleID, Success: false, Details: map[string]interface{}{"reason": "handling_noncompliant"}})
		writeError(w, apiErr(400, "handling_noncompliant", "observed temperature outside required range"))
		return
	}
	sealedAt := time.Now().UTC().Format(time.RFC3339)
	_, err = a.store.PG.Exec(ctx, `UPDATE samples SET sealed=true, status='sealed', current_holder_id=$1 WHERE id=$2`, au.ID, asn.SampleID)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	_, err = a.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, asn.ID)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	if body.Temperature != nil {
		_, _ = a.store.PG.Exec(ctx, `INSERT INTO checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, compliant)
			VALUES ($1,$2,$3,$4,$5)`, asn.SampleID, asn.ID, body.ContainerType, *body.Temperature, compliant)
	}
	a.store.recordSampleEvent(ctx, asn.SampleID, "collected_and_sealed", au.ID, map[string]interface{}{"containerType": body.ContainerType})
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "collect_and_seal",
		EntityType: "sample", EntityID: asn.SampleID, Success: true})
	a.store.offerNextAssignment(ctx, asn.JourneyID, asn.SampleID)
	resp := map[string]interface{}{"sampleId": asn.SampleID, "status": "sealed", "currentHolderId": au.ID, "sealedAt": sealedAt, "handlingCompliant": compliant}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "collect_and_seal_sample")
}

// handleRecordWorkerLocation POST /api/record-worker-location
func (a *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		AssignmentID string             `json:"assignmentId"`
		Coordinate   map[string]float64 `json:"coordinate"`
		Sequence     *int               `json:"sequence"`
		RecordedAt   string             `json:"recordedAt"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.Coordinate == nil {
		writeError(w, apiErr(400, "invalid_coordinate", "coordinate required"))
		return
	}
	if _, ok := body.Coordinate["latitude"]; !ok {
		writeError(w, apiErr(400, "invalid_coordinate", "latitude required"))
		return
	}
	if _, ok := body.Coordinate["longitude"]; !ok {
		writeError(w, apiErr(400, "invalid_coordinate", "longitude required"))
		return
	}
	if body.Sequence == nil || *body.Sequence < 1 {
		writeError(w, apiErr(400, "invalid_sequence", "sequence must be >= 1"))
		return
	}
	if _, e := parseTimeField(body.RecordedAt); e != nil {
		writeError(w, apiErr(400, "invalid_time", "recordedAt invalid"))
		return
	}
	ctx := r.Context()
	if body.AssignmentID != "" {
		asn, err := a.store.getAssignment(ctx, body.AssignmentID)
		if err != nil {
			writeError(w, errNotFound)
			return
		}
		if asn.WorkerID == nil || *asn.WorkerID != au.ID {
			writeError(w, apiErr(403, "forbidden", "not your assignment"))
			return
		}
	}
	// Sequence monotonicity (stale) check.
	var lastSeq int
	_ = a.store.PG.QueryRow(ctx, `SELECT COALESCE(max(sequence),0) FROM worker_locations WHERE worker_id=$1`, au.ID).Scan(&lastSeq)
	if *body.Sequence <= lastSeq {
		writeError(w, apiErr(409, "stale_location", "sequence must be greater than last recorded"))
		return
	}
	recAt, _ := parseTimeField(body.RecordedAt)
	_, err := a.store.PG.Exec(ctx, `INSERT INTO worker_locations (worker_id, lat, lon, sequence, recorded_at, available)
		VALUES ($1,$2,$3,$4,$5,true)
		ON CONFLICT (worker_id) DO UPDATE SET lat=$2, lon=$3, sequence=$4, recorded_at=$5`,
		au.ID, body.Coordinate["latitude"], body.Coordinate["longitude"], *body.Sequence, recAt)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "record_worker_location",
		EntityType: "worker", EntityID: au.ID, Success: true})
	coord := map[string]interface{}{"latitude": body.Coordinate["latitude"], "longitude": body.Coordinate["longitude"]}
	writeData(w, 201, map[string]interface{}{"assignmentId": body.AssignmentID, "coordinate": coord, "sequence": *body.Sequence, "recordedAt": body.RecordedAt})
}

// handleSetWorkerAvailability POST /api/set-worker-availability
func (a *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.CapacityUnits == nil || *body.CapacityUnits < 0 {
		writeError(w, apiErr(400, "invalid_capacity", "capacityUnits must be >= 0"))
		return
	}
	ctx := r.Context()
	target := body.WorkerID
	if target == "" {
		target = au.ID
	}
	// Only the worker themselves or an admin/dispatcher may set availability.
	if target != au.ID {
		if e := requireRole(r, "dispatcher", "administrator"); e != nil {
			writeError(w, e)
			return
		}
		if _, err := a.store.getUser(ctx, target); err != nil {
			writeError(w, errNotFound)
			return
		}
	}
	_, err := a.store.PG.Exec(ctx, `INSERT INTO worker_locations (worker_id, lat, lon, sequence, recorded_at, available, capacity_units)
		VALUES ($1,0,0,1,now(),$2,$3)
		ON CONFLICT (worker_id) DO UPDATE SET available=$2, capacity_units=$3`,
		target, body.Available, *body.CapacityUnits)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "set_worker_availability",
		EntityType: "worker", EntityID: target, Success: true, Details: map[string]interface{}{"available": body.Available, "capacityUnits": *body.CapacityUnits}})
	writeData(w, 200, map[string]interface{}{"workerId": target, "available": body.Available, "capacityUnits": *body.CapacityUnits})
}

// handleUpdateAssignmentProgress POST /api/update-assignment-progress
func (a *App) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		AssignmentID  string `json:"assignmentId"`
		Status        string `json:"status"`
		OccurredAt    string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	if _, e := parseTimeField(body.OccurredAt); e != nil {
		writeError(w, apiErr(400, "invalid_time", "occurredAt invalid"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "update_assignment_progress", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	asn, err := a.store.getAssignment(ctx, body.AssignmentID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	if asn.Status == "completed" || asn.Status == "cancelled" {
		writeError(w, apiErr(409, "assignment_inactive", "assignment is "+asn.Status))
		return
	}
	if asn.WorkerID == nil || *asn.WorkerID != au.ID {
		writeError(w, apiErr(403, "ineligible_worker", "not your assignment"))
		return
	}
	if asn.Status != "accepted" && asn.Status != "in_progress" {
		writeError(w, apiErr(409, "assignment_not_ready", "assignment is "+asn.Status))
		return
	}
	// Validate transition ordering: collection must complete before transport; custody required for in_transit.
	newStatus := body.Status
	if asn.Kind == "transport" {
		// Transport requires sealed sample (collection done) before pickup.
		var sealed bool
		_ = a.store.PG.QueryRow(ctx, `SELECT sealed FROM samples WHERE id=$1`, asn.SampleID).Scan(&sealed)
		if !sealed && (newStatus == "picked_up" || newStatus == "in_transit" || newStatus == "arrived" || newStatus == "delivered") {
			writeError(w, apiErr(409, "collection_required", "sample must be collected and sealed first"))
			return
		}
	}
	if newStatus == "in_progress" && asn.Kind == "transport" {
		// Require custody: current holder must be this worker.
		var holder *string
		_ = a.store.PG.QueryRow(ctx, `SELECT current_holder_id FROM samples WHERE id=$1`, asn.SampleID).Scan(&holder)
		if holder == nil || *holder != au.ID {
			writeError(w, apiErr(409, "custody_required", "you must hold custody before in_transit"))
			return
		}
	}
	finalStatus := newStatus
	if newStatus == "in_progress" && asn.Status != "in_progress" {
		_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='in_progress' WHERE id=$1`, body.AssignmentID)
	}
	if newStatus == "completed" || newStatus == "delivered" {
		finalStatus = "completed"
		_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, body.AssignmentID)
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "update_assignment_progress",
		EntityType: "assignment", EntityID: body.AssignmentID, Success: true, Details: map[string]interface{}{"status": newStatus}})
	resp := map[string]interface{}{"assignmentId": body.AssignmentID, "sampleId": asn.SampleID, "status": finalStatus}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "update_assignment_progress")
}

