	}
	if toAsn.JourneyID != fromAsn.JourneyID {
		writeError(w, apiErr(409, "nonadjacent_handoff", "assignments belong to different journeys"))
		return
	}
	if toAsn.Sequence != fromAsn.Sequence+1 {
		writeError(w, apiErr(409, "nonadjacent_handoff", "to assignment is not the next leg"))
		return
	}
	if toAsn.SampleID != body.SampleID {
		writeError(w, apiErr(409, "receiver_assignment_mismatch", "sample does not match to assignment"))
		return
	}
	// Receiver must match the assigned worker or be eligible at the destination node/lab.
	if toAsn.WorkerID == nil || *toAsn.WorkerID != body.ReceiverID {
		writeError(w, apiErr(409, "receiver_assignment_mismatch", "receiver is not the assigned worker of the to assignment"))
		return
	}
	// No duplicate pending handoff.
	var existing string
	_ = a.store.PG.QueryRow(ctx, `SELECT id FROM handoffs WHERE from_assignment_id=$1 AND status='pending' LIMIT 1`, body.FromAssignID).Scan(&existing)
	if existing != "" {
		writeError(w, apiErr(409, "pending_handoff_exists", "a pending handoff already exists"))
		return
	}
	// Prior leg must be complete (collection/transport done) — sender must hold a sealed sample.
	var sealed bool
	_ = a.store.PG.QueryRow(ctx, `SELECT sealed FROM samples WHERE id=$1`, body.SampleID).Scan(&sealed)
	if !sealed {
		writeError(w, apiErr(409, "prior_leg_incomplete", "sample must be sealed before handoff"))
		return
	}
	var handoffID string
	err = a.store.PG.QueryRow(ctx, `INSERT INTO handoffs (sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
		VALUES ($1,$2,$3,$4,$5,'pending',$6) RETURNING id`,
		body.SampleID, body.FromAssignID, body.ToAssignID, au.ID, body.ReceiverID, initAt).Scan(&handoffID)
	if err != nil {
		writeError(w, apiErr(409, "pending_handoff_exists", err.Error()))
		return
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "initiate_handoff",
		EntityType: "handoff", EntityID: handoffID, Success: true})
	resp := map[string]interface{}{"handoffId": handoffID, "senderId": au.ID, "receiverId": body.ReceiverID, "currentHolderId": au.ID, "status": "pending"}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "initiate_handoff")
}

// handleConfirmHandoff POST /api/confirm-handoff
func (a *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		HandoffID      string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt    string `json:"confirmedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	_, e := parseTimeField(body.ConfirmedAt)
	if e != nil {
		writeError(w, apiErr(400, "invalid_time", "confirmedAt invalid"))
		return
	}
	if body.ConfirmationSide != "sender" && body.ConfirmationSide != "receiver" {
		writeError(w, apiErr(400, "invalid_confirmation_side", "confirmationSide must be sender or receiver"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "confirm_handoff", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	var sampleID, receiverID, senderID string
	var senderConf, recvConf bool
	var status, fromAssignID, toAssignID string
	err := a.store.PG.QueryRow(ctx, `SELECT sample_id, sender_id, receiver_id, sender_confirmed, receiver_confirmed, status, from_assignment_id, to_assignment_id FROM handoffs WHERE id=$1`, body.HandoffID).
		Scan(&sampleID, &senderID, &receiverID, &senderConf, &recvConf, &status, &fromAssignID, &toAssignID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	if status == "completed" {
		writeError(w, apiErr(409, "handoff_inactive", "handoff already completed"))
		return
	}
	// Validate side against the user.
	switch body.ConfirmationSide {
	case "sender":
		if au.ID != senderID {
			writeError(w, apiErr(403, "forbidden", "you are not the sender"))
			return
		}
		_, _ = a.store.PG.Exec(ctx, `UPDATE handoffs SET sender_confirmed=true WHERE id=$1`, body.HandoffID)
		senderConf = true
	case "receiver":
		if au.ID != receiverID {
			writeError(w, apiErr(403, "forbidden", "you are not the receiver"))
			return
		}
		_, _ = a.store.PG.Exec(ctx, `UPDATE handoffs SET receiver_confirmed=true WHERE id=$1`, body.HandoffID)
		recvConf = true
	}
	currentHolder := senderID
	completed := false
	if senderConf && recvConf {
		_, _ = a.store.PG.Exec(ctx, `UPDATE handoffs SET status='completed', confirmed_at=now() WHERE id=$1`, body.HandoffID)
		_, _ = a.store.PG.Exec(ctx, `UPDATE samples SET current_holder_id=$1 WHERE id=$2`, receiverID, sampleID)
		_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, fromAssignID)
		_, _ = a.store.PG.Exec(ctx, `DELETE FROM capacity_reservations WHERE assignment_id=$1`, fromAssignID)
		a.store.recordSampleEvent(ctx, sampleID, "custody_transferred", au.ID, map[string]interface{}{"from": senderID, "to": receiverID})
		currentHolder = receiverID
		completed = true
	}
	statusResp := "pending"
	if completed {
		statusResp = "confirmed"
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "confirm_handoff",
		EntityType: "handoff", EntityID: body.HandoffID, Success: true})
	resp := map[string]interface{}{"handoffId": body.HandoffID, "status": statusResp, "senderConfirmed": senderConf, "receiverConfirmed": recvConf, "currentHolderId": currentHolder}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "confirm_handoff")
}

// handleRecordHandlingCheckpoint POST /api/record-handling-checkpoint
func (a *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		SampleID      string  `json:"sampleId"`
		AssignmentID  string  `json:"assignmentId"`
		LocationID    string  `json:"locationId"`
		ContainerType string  `json:"containerType"`
		ObservedTempC float64 `json:"observedTemperatureC"`
		RecordedAt    string  `json:"recordedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	recAt, e := parseTimeField(body.RecordedAt)
	if e != nil {
		writeError(w, apiErr(400, "invalid_time", "recordedAt invalid"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "record_handling_checkpoint", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	// Verify the holder.
	var holderID *string
	var sampleStatus string
	_ = a.store.PG.QueryRow(ctx, `SELECT current_holder_id, status FROM samples WHERE id=$1`, body.SampleID).Scan(&holderID, &sampleStatus)
	if holderID == nil {
		writeError(w, errNotFound)
		return
	}
	if *holderID != au.ID {
		writeError(w, apiErr(403, "forbidden", "you are not the current holder"))
		return
	}
	if sampleStatus == "received" || sampleStatus == "exception" || sampleStatus == "expired" || sampleStatus == "cancelled" {
		writeError(w, apiErr(409, "terminal_sample", "sample is in terminal state "+sampleStatus))
		return
	}
	// Assignment must belong to this holder and not be inactive.
	if body.AssignmentID != "" {
		asn, err := a.store.getAssignment(ctx, body.AssignmentID)
		if err != nil {
			writeError(w, errNotFound)
			return
		}
		if asn.WorkerID == nil || *asn.WorkerID != au.ID {
			writeError(w, apiErr(403, "forbidden", "assignment does not belong to you"))
			return
		}
		if asn.Status == "completed" || asn.Status == "cancelled" {
			writeError(w, apiErr(409, "assignment_inactive", "assignment is "+asn.Status))
			return
		}
	}
	var tempMin, tempMax *float64
	var requiredContainer string
	_ = a.store.PG.QueryRow(ctx, `SELECT st.temp_min, st.temp_max, st.container_type FROM samples s JOIN sample_types st ON st.id=s.sample_type_id WHERE s.id=$1`, body.SampleID).Scan(&tempMin, &tempMax, &requiredContainer)
	compliant := true
	if tempMin != nil && body.ObservedTempC < *tempMin {
		compliant = false
	}
	if tempMax != nil && body.ObservedTempC > *tempMax {
		compliant = false
	}
	if body.ContainerType != "" && requiredContainer != "" && body.ContainerType != requiredContainer {
		compliant = false
	}
	var locID *string
	if body.LocationID != "" {
		locID = &body.LocationID
	}
	var checkpointID string
	err := a.store.PG.QueryRow(ctx, `INSERT INTO checkpoints (sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant)
		VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id`,
		body.SampleID, nullableStr(body.AssignmentID), locID, body.ContainerType, body.ObservedTempC, recAt, compliant).Scan(&checkpointID)
	if err != nil {
		writeError(w, errInternal)
		return
	}
	finalStatus := sampleStatus
	if !compliant {
		_, _ = a.store.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1 WHERE id=$2`,
			pgJSONStr(map[string]interface{}{"reason": "handling_noncompliant", "flaggedAt": time.Now().UTC().Format(time.RFC3339)}), body.SampleID)
		a.store.recordSampleEvent(ctx, body.SampleID, "exception", au.ID, map[string]interface{}{"reason": "handling_noncompliant"})
		finalStatus = "exception"
	}
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "record_handling_checkpoint",
		EntityType: "sample", EntityID: body.SampleID, Success: true, Details: map[string]interface{}{"compliant": compliant}})
	resp := map[string]interface{}{"checkpointId": checkpointID, "sampleId": body.SampleID, "compliant": compliant, "sampleStatus": finalStatus}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "record_handling_checkpoint")
}

// handleConfirmLabReceipt POST /api/confirm-laboratory-receipt
func (a *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	au := currentUser(r)
	if e := requireRole(r, "laboratory_team"); e != nil {
		writeError(w, e)
		return
	}
	var body struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		ReceivedAt    string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := parseBody(r, &body); e != nil {
		writeError(w, e)
		return
	}
	if body.IdempotencyKey == "" {
		writeError(w, errIdemRequired)
		return
	}
	recAt, e := parseTimeField(body.ReceivedAt)
	if e != nil {
		writeError(w, apiErr(400, "invalid_time", "receivedAt invalid"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "confirm_laboratory_receipt", true); e != nil {
		writeError(w, e)
		return
	} else if key != "" {
		return
	}
	// Laboratory operator must be assigned to this laboratory.
	var assignedLoc *string
	_ = a.store.PG.QueryRow(ctx, `SELECT assigned_location_id FROM users WHERE id=$1`, au.ID).Scan(&assignedLoc)
	if assignedLoc == nil || *assignedLoc != body.LaboratoryID {
		writeError(w, apiErr(403, "wrong_laboratory_operator", "you are not assigned to this laboratory"))
		return
	}
	// Laboratory must be active and accept this sample type.
	var labActive bool
	_ = a.store.PG.QueryRow(ctx, `SELECT active FROM locations WHERE id=$1`, body.LaboratoryID).Scan(&labActive)
	if !labActive {
		writeError(w, apiErr(409, "laboratory_unavailable", "laboratory is not active"))
		return
	}
	var holderID *string
	var sampleStatus string
	var deadline *time.Time
	_ = a.store.PG.QueryRow(ctx, `SELECT current_holder_id, status, deadline FROM samples WHERE id=$1`, body.SampleID).Scan(&holderID, &sampleStatus, &deadline)
	if holderID == nil {
		writeError(w, errNotFound)
		return
	}
	if *holderID != au.ID {
		writeError(w, apiErr(409, "custody_conflict", "you do not hold custody of this sample"))
		return
	}
	if sampleStatus == "received" {
		writeError(w, apiErr(409, "receipt_not_ready", "sample already received"))
		return
	}
	if sampleStatus != "sealed" && sampleStatus != "in_transit" {
		writeError(w, apiErr(409, "receipt_not_ready", "sample is "+sampleStatus))
		return
	}
	// No pending handoff should block receipt.
	var pending string
	_ = a.store.PG.QueryRow(ctx, `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, body.SampleID).Scan(&pending)
	if pending != "" {
		writeError(w, apiErr(409, "pending_handoff_exists", "a pending handoff must be confirmed first"))
		return
	}
	if deadline != nil && recAt.After(*deadline) {
		writeError(w, apiErr(409, "delivery_deadline_exceeded", "received after delivery deadline"))
		return
	}
	_, err := a.store.PG.Exec(ctx, `UPDATE samples SET status='received', current_holder_id=$1 WHERE id=$2`, au.ID, body.SampleID)
	if err != nil {
		writeError(w, errNotFound)
		return
	}
	// Complete the laboratory assignment, if any.
	_, _ = a.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=now() WHERE sample_id=$1 AND kind='laboratory_receipt'`, body.SampleID)
	_, _ = a.store.PG.Exec(ctx, `DELETE FROM capacity_reservations WHERE sample_id=$1`, body.SampleID)
	a.store.recordSampleEvent(ctx, body.SampleID, "received_at_laboratory", au.ID, nil)
	a.store.audit(ctx, AuditEntry{ActorID: au.ID, Role: currentRole(r), ActorRole: currentRole(r), Action: "confirm_laboratory_receipt",
		EntityType: "sample", EntityID: body.SampleID, Success: true})
	resp := map[string]interface{}{"sampleId": body.SampleID, "laboratoryId": body.LaboratoryID, "status": "received", "receivedAt": body.ReceivedAt}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "confirm_laboratory_receipt")
}

