	}
	obsAt, e := parseTimeField(body.ObservedAt)
	if e != nil {
		writeError(w, apiErr(400, "invalid_time", "observedAt invalid"))
		return
	}
	ctx := r.Context()
	if key, e := a.idempotencyLookup(w, r, body.IdempotencyKey, "record_laboratory_exception", true); e != nil {
