		EntityType: "sample", EntityID: body.SampleID, Success: true, Details: map[string]interface{}{"reason": body.Reason}})
	resp := map[string]interface{}{"exceptionId": exceptionID, "sampleId": body.SampleID, "status": "exception", "reason": body.Reason}
	a.writeDataIDem(w, r, 201, resp, body.IdempotencyKey, "record_laboratory_exception")
}

