action.command:
cd /workspace && python3 -c "
import json
c=json.load(open('contracts/openapi.contract.json'))
for opid in ['initiate_handoff','confirm_handoff','record_handling_checkpoint','confirm_laboratory_receipt','record_laboratory_exception']:
    for p,methods in c['paths'].items():
        for m,op in methods.items():
            if op.get('operationId')==opid:
                print('====',opid, m.upper(), p)
                rb=op.get('requestBody',{})
                print('REQ:', json.dumps(rb, indent=1)[:2000])
                for code,resp in op.get('responses',{}).items():
                    print('RESP',code,':', json.dumps(resp.get('content',{}), indent=1)[:1500])
"

