// idempotencyLookup returns a previously stored response for the given key+op
// if one exists, writing it directly to w and returning (true, nil). When the
// key is required but absent it returns an idempotency_required error.
func (a *App) idempotencyLookup(w http.ResponseWriter, r *http.Request, key, op string, required bool) (string, *errAPI) {
        if key == "" {
                if required {
                        return "", errIdemRequired
                }
                return "", nil
        }
        ctx := r.Context()
        var payload []byte
        var code int
        err := a.store.PG.QueryRow(ctx, `SELECT response, status_code FROM idempotency_keys WHERE key=$1 AND operation=$2`, key, op).Scan(&payload, &code)
        if err == nil {
                w.Header().Set("Content-Type", "application/json")
                w.WriteHeader(code)
                _, _ = w.Write(payload)
                return key, nil
        }
        return key, nil
}

// idempotencyStore persists a response keyed by (key, op).
func (a *App) idempotencyStore(r *http.Request, key, op string, status int, body []byte) {
        if key == "" {
                return
        }
        au := currentUser(r)
        var uid interface{}
        if au != nil {
                uid = au.ID
        }
        _, _ = a.store.PG.Exec(r.Context(), `INSERT INTO idempotency_keys (key, user_id, operation, response, status_code) VALUES ($1,$2,$3,$4,$5) ON CONFLICT (key) DO NOTHING`, key, uid, op, body, status)
}

// writeDataIDem writes a data-wrapped JSON response and records it for idempotency.
func (a *App) writeDataIDem(w http.ResponseWriter, r *http.Request, status int, data interface{}, key, op string) {
        b, _ := json.Marshal(map[string]interface{}{"data": data})
        w.Header().Set("Content-Type", "application/json")
        w.WriteHeader(status)
        _, _ = w.Write(b)
        a.idempotencyStore(r, key, op, status, b)
}

